'use client';
import { useCallback, useEffect, useRef, useState } from 'react';
import Image from 'next/image';

type Action = {text: string; kind: 'core'|'other'; minutes: number|null};
type HabitPlanSchedule = {start_date:string;end_date:string;timezone:string;weekdays:number[];completion_standard:string;growth_threshold:number};
type Constraints = {session_budget_minutes: number|null; habit_completion_minutes: number|null; habit_schedule?: HabitPlanSchedule|null};
type FlowerSpecies = 'sunflower'|'daisy'|'tulip';
const flowerNames:Record<FlowerSpecies,string>={sunflower:'向日葵',daisy:'雏菊',tulip:'郁金香'};
type Plan = { title: string; summary: string; steps: string[]; session_actions?: Action[]|null; growth_nodes?: number[]|null; flower_species?: FlowerSpecies|null; flower_reason?: string|null };
type Plant = { id: string; title: string; kind: string; plan: Plan; constraints?: Constraints };
type GoalAction = {index: number; text: string; completed: boolean; due_date:string|null; cancelled:boolean};
type TodayGoal = {plant_id:string;plant_title:string;stage_id?:string; index:number; text:string; due_date:string|null; completed:boolean};
type TodayHabit = {plant_id:string;plant_title:string; date:string; completed:boolean; completion_standard:string};
type Today = {date:string;goals_today:TodayGoal[];goals_overdue:TodayGoal[];goals_unscheduled:TodayGoal[];habits_today:TodayHabit[];habits_backfill:TodayHabit[]};

type CareMessage={id:string;plant_id:string;plant_title:string;text:string};
function CareBox({onOpenPlant}:{onOpenPlant:(id:string)=>void}) {
  const [open,setOpen]=useState(false);const container=useRef<HTMLDivElement>(null);const [enabled,setEnabled]=useState(true);const [messages,setMessages]=useState<CareMessage[]>([]);const [loaded,setLoaded]=useState(false);const [busy,setBusy]=useState(false);const [error,setError]=useState('');
  const load=useCallback(async(refresh:boolean)=>{try{if(refresh){const r=await fetch('/api/v1/care/refresh',{method:'POST'});if(!r.ok)throw new Error();}const r=await fetch('/api/v1/care');if(!r.ok)throw new Error();const d=await r.json();setEnabled(d.enabled);setMessages(d.messages);setLoaded(true);setError('');}catch{setError('园丁留言暂时无法读取。');}},[]);
  useEffect(()=>{void load(true);const refresh=()=>void load(true);window.addEventListener('bloomate-progress',refresh);return()=>window.removeEventListener('bloomate-progress',refresh);},[load]);
  useEffect(()=>{if(!open)return;const outside=(event:MouseEvent)=>{if(!container.current?.contains(event.target as Node))setOpen(false);};const keyboard=(event:KeyboardEvent)=>{if(event.key==='Escape')setOpen(false);};document.addEventListener('mousedown',outside);document.addEventListener('keydown',keyboard);return()=>{document.removeEventListener('mousedown',outside);document.removeEventListener('keydown',keyboard);};},[open]);
  async function toggle(){setBusy(true);try{const r=await fetch('/api/v1/care/preference',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:!enabled})});if(!r.ok)throw new Error();await load(!enabled);}catch{setError('设置暂时无法保存。');}finally{setBusy(false);}}
  async function dismiss(id:string){setBusy(true);try{const r=await fetch(`/api/v1/care/${id}/dismiss`,{method:'POST'});if(!r.ok)throw new Error();await load(false);}catch{setError('留言暂时无法忽略。');}finally{setBusy(false);}}
  return <div className="care-menu" ref={container}><button type="button" className="care-trigger" aria-expanded={open} aria-controls="care-panel" onClick={()=>setOpen(!open)}>园丁留言 {enabled && messages.length>0 && <span className="care-count" aria-label={`${messages.length} 条留言`}>{messages.length}</span>}</button>{open && <section className="care-panel" id="care-panel" aria-label="园丁留言"><div className="care-heading"><div><span className="eyebrow">A NOTE FROM YOUR GARDENER</span><h2>园丁留言</h2></div><button type="button" className="care-close" aria-label="关闭留言面板" onClick={()=>setOpen(false)}>×</button></div>{error && <p role="alert">{error} <button type="button" onClick={()=>void load(false)}>重试</button></p>}{!loaded && !error ? <p className="muted">正在读取留言…</p> : !enabled ? <p className="muted">园丁关心已关闭，你可以随时重新开启。</p> : messages.length ? <ul>{messages.map(m=><li key={m.id}><strong>{m.plant_title}</strong><p>{m.text}</p><button type="button" onClick={()=>{setOpen(false);onOpenPlant(m.plant_id);}}>去看看</button> <button type="button" disabled={busy} onClick={()=>void dismiss(m.id)}>忽略</button></li>)}</ul> : <p className="muted">暂时没有留言。园丁不会自动修改你的计划。</p>}<div className="care-settings"><span>同一株植物每七天最多一条。</span><button type="button" disabled={busy||!loaded} onClick={()=>void toggle()}>{enabled?'关闭关心':'开启关心'}</button></div></section>}</div>;
}

function TodayActions({onOpenPlant,onCreate,plants,gardenStatus,onReloadGarden}: {onOpenPlant:(id:string)=>void;onCreate:()=>void;plants:Plant[];gardenStatus:'loading'|'ready'|'error';onReloadGarden:()=>void}) {
  const [today,setToday]=useState<Today|null>(null);const [error,setError]=useState('');const [feedback,setFeedback]=useState('');const [busy,setBusy]=useState(false);const [pending,setPending]=useState<{plant_id:string;title:string;kind:string}[]>([]);const [lastUndo,setLastUndo]=useState<{kind:'goal';item:TodayGoal}|{kind:'habit';item:TodayHabit}|null>(null);
  const load=useCallback(async()=>{const [a,b]=await Promise.all([fetch('/api/v1/today'),fetch('/api/v1/completion-notices')]);if(!a.ok||!b.ok)throw new Error();setToday(await a.json());setPending((await b.json()).notices);setError('');},[]);
  useEffect(()=>{const refresh=()=>{void load().catch(()=>setError('今日行动暂时无法读取。'));};refresh();window.addEventListener('bloomate-progress',refresh);return()=>window.removeEventListener('bloomate-progress',refresh);},[load]);
  async function goal(a:TodayGoal){setBusy(true);setError('');setFeedback('');try{const url=a.stage_id?`/api/v1/goal-stages/${a.stage_id}/actions/${a.index}`:`/api/v1/plants/${a.plant_id}/actions/${a.index}`;const r=await fetch(url,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({completed:!a.completed})});const d=await r.json();if(!r.ok)throw new Error(d.error?.message||'暂时无法保存。');setFeedback(d.completed?'已完成，行动已记录。':'已撤销完成记录。');setLastUndo(d.completed?{kind:'goal',item:{...a,completed:true}}:null);window.dispatchEvent(new Event('bloomate-progress'));}catch(e){setError(e instanceof Error?e.message:'暂时无法保存。');}finally{setBusy(false);}}
  async function habit(a:TodayHabit,backfill=false){if(backfill&&!window.confirm(`确认 ${a.date} 当天确实完成了吗？`))return;setBusy(true);setError('');setFeedback('');try{const r=await fetch(`/api/v1/plants/${a.plant_id}/habit-occurrences/${a.date}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({completed:!a.completed,performed:!a.completed})});const d=await r.json();if(!r.ok)throw new Error(d.error?.message||'暂时无法保存。');setFeedback(d.completed?'打卡成功，行动已记录。':'已撤销打卡记录。');setLastUndo(d.completed?{kind:'habit',item:{...a,completed:true}}:null);window.dispatchEvent(new Event('bloomate-progress'));}catch(e){setError(e instanceof Error?e.message:'暂时无法保存。');}finally{setBusy(false);}}
  async function choose(choice:'finish'|'continue'){const item=pending[0];if(!item)return;setBusy(true);setError('');try{const r=await fetch(`/api/v1/plants/${item.plant_id}/completion-notice`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({choice})});const d=await r.json();if(!r.ok)throw new Error(d.error?.message||'暂时无法保存选择。');await load();window.dispatchEvent(new Event('bloomate-progress'));if(choice==='continue'){onOpenPlant(item.plant_id);const openForm=(left:number)=>{const el=document.getElementById(`next-${item.kind}-${item.plant_id}`);if(el)el.scrollIntoView({block:'start',behavior:'smooth'});else if(left>0)setTimeout(()=>openForm(left-1),150);};setTimeout(()=>openForm(20),150);}else setFeedback('这个阶段已完成，花和记录已收藏。');}catch(e){setError(e instanceof Error?e.message:'暂时无法保存选择。');}finally{setBusy(false);}}
  const icon=(completed:boolean,number?:number)=>number===undefined?null:<span className="today-number">{completed?<span className="today-completed-icon" role="img" aria-label="已完成"><svg viewBox="0 0 20 20" aria-hidden="true"><path d="M5.5 10.2 8.5 13.1 14.7 6.8"/></svg></span>:String(number).padStart(2,'0')}</span>;
  const goalRow=(a:TodayGoal,number?:number)=><li className={number!==undefined?'today-action-row'+(a.completed?' is-done':''):undefined} key={`${a.plant_id}-${a.stage_id||'initial'}-${a.index}`}>{icon(a.completed,number)}<div className="today-action-copy"><span className="today-owner">目标 · {a.plant_title}</span><span className="today-task">{a.text}{number===undefined && a.completed && <span className="done-label">已完成</span>}</span>{a.due_date && a.due_date!==today?.date && <span className="today-meta">{a.due_date}</span>}</div><div className="today-actions"><button type="button" disabled={busy} aria-label={a.completed?`撤销${a.text}的完成记录`:undefined} onClick={()=>void goal(a)}>{a.completed?'撤销':'标记完成'}</button><button type="button" className="text-button" onClick={()=>onOpenPlant(a.plant_id)}>看植物</button></div></li>;
  const habitRow=(a:TodayHabit,backfill=false,number?:number)=><li className={number!==undefined?'today-action-row'+(a.completed?' is-done':''):undefined} key={`habit-${a.plant_id}-${a.date}`}>{icon(a.completed,number)}<div className="today-action-copy"><span className="today-owner">习惯 · {a.plant_title}</span><span className="today-task">{a.completion_standard}{number===undefined && a.completed && <span className="done-label">已完成</span>}</span>{backfill && <span className="today-meta">{a.date} · 补签</span>}</div><div className="today-actions"><button type="button" disabled={busy} aria-label={a.completed?`撤销${a.plant_title}的打卡记录`:undefined} onClick={()=>void habit(a,backfill)}>{a.completed?'撤销':backfill?'补签':'完成打卡'}</button><button type="button" className="text-button" onClick={()=>onOpenPlant(a.plant_id)}>看植物</button></div></li>;
  const actions=today?[...today.goals_today.map(item=>({kind:'goal' as const,item})),...today.habits_today.map(item=>({kind:'habit' as const,item}))]:[];
  const sortedActions=[...actions.filter(a=>!a.item.completed),...actions.filter(a=>a.item.completed)];
  const completedCount=actions.filter(a=>a.item.completed).length;
  const dateLabel=today?new Intl.DateTimeFormat('zh-CN',{timeZone:'UTC',year:'numeric',month:'long',day:'numeric',weekday:'long'}).format(new Date(`${today.date}T00:00:00Z`)):'';

  return <section className="today-view">{pending.length>0 && <div className="completion-overlay"><div className="completion-dialog" role="dialog" aria-modal="true" aria-labelledby="today-completion"><h2 id="today-completion">这一阶段完成了，花开了！</h2><p>{pending[0].title}的花和记录会留在花园里。接下来你想怎么做？</p><button type="button" autoFocus disabled={busy} onClick={()=>void choose('finish')}>完成</button> <button type="button" disabled={busy} onClick={()=>void choose('continue')}>继续下一阶段</button>{error && <p role="alert">{error}</p>}</div></div>}{error && <p className="message" role="status">{error}</p>}{feedback && <p className="message" role="status">{feedback} {lastUndo && <button type="button" className="text-button" disabled={busy} onClick={()=>void (lastUndo.kind==='goal'?goal(lastUndo.item):habit(lastUndo.item))}>撤销这次记录</button>}</p>}{!today && !error && <p className="muted">正在读取今日行动…</p>}{today && <div className="today-grid"><section className="card today-main"><div className="view-heading today-heading"><div><div className="eyebrow">{dateLabel}</div><h1>今天，慢慢来。</h1><p>看看今天要做什么，也给自己留一点空间。</p></div><div className="today-heading-actions"><button type="button" className="outline-button" onClick={onCreate}>＋ 制定新计划</button><span className="today-count" aria-live="polite">已完成 {completedCount} / {actions.length}</span></div></div>{today.goals_today.length+today.habits_today.length===0 ? <div className="today-empty"><span aria-hidden="true">✿</span><strong>今天还没有安排</strong><p>你可以制定计划，或者查看待安排日期的步骤。</p><button type="button" className="text-button" onClick={onCreate}>和园丁聊聊 →</button></div> : <ul className="today-list">{sortedActions.map((a,i)=>a.kind==='goal'?goalRow(a.item,i+1):habitRow(a.item,false,i+1))}</ul>}</section><aside className="today-side"><TodayPlant key={(today.habits_today[0] ?? today.goals_today[0])?.plant_id ?? plants[0]?.id ?? gardenStatus} plants={plants} today={today} gardenStatus={gardenStatus} onReloadGarden={onReloadGarden} onOpenPlant={onOpenPlant}/><details className="card queue-card" open={today.goals_overdue.length>0}><summary>逾期未完成 <span className="count-badge">{today.goals_overdue.length}</span></summary>{today.goals_overdue.length?<ul className="today-list">{today.goals_overdue.map(a=>goalRow(a))}</ul>:<p className="muted">没有逾期步骤。</p>}</details><details className="card queue-card"><summary>待安排日期 <span className="count-badge">{today.goals_unscheduled.length}</span></summary>{today.goals_unscheduled.length?<ul className="today-list">{today.goals_unscheduled.map(a=>goalRow(a))}</ul>:<p className="muted">没有待安排的目标步骤。</p>}</details><details className="card queue-card"><summary>补签习惯 <span className="count-badge">{today.habits_backfill.length}</span></summary><p className="note">仅补记过去三天实际完成的行动。</p>{today.habits_backfill.length?<ul className="today-list">{today.habits_backfill.map(a=>habitRow(a,true))}</ul>:<p className="muted">没有可补签的计划日。</p>}</details><p className="timezone-note">目标日期按北京时间；习惯按各自周期的时区计算。</p></aside></div>}</section>;
}

type Adjustment = {id:string; status:string; original_text:string; suggestion:string|null; suggestion_steps:string[]|null; step_index:number; error?:{message:string}};

function AdjustmentEditor({plantId, actions, onChanged}: {plantId:string; actions:GoalAction[]; onChanged:()=>Promise<void>}) {
  const [selected,setSelected]=useState(''); const [difficulty,setDifficulty]=useState('');
  const [draft,setDraft]=useState<Adjustment|null>(null); const [edited,setEdited]=useState('');
  const [busy,setBusy]=useState(false); const [message,setMessage]=useState('');
  const storageKey=`bloomate-adjustment-${plantId}`;
  const poll=useCallback(async (id:string) => {
    for (let i=0;i<75;i++) {
      const response=await fetch(`/api/v1/adjustments/${id}`); const data:Adjustment=await response.json();
      if (!response.ok) throw new Error('无法读取调整建议。');
      if (data.status==='error') throw new Error(data.error?.message || '建议生成失败，请重试。');
      if (data.status==='done') {setDraft(data);setEdited((data.suggestion_steps || (data.suggestion?[data.suggestion]:[])).join('\n'));return;}
      if (data.status==='confirmed' || data.status==='discarded') {localStorage.removeItem(storageKey);return;}
      await new Promise(resolve=>setTimeout(resolve,1000));
    }
    throw new Error('等待时间较长，刷新后可继续查看。');
  },[storageKey]);
  useEffect(()=>{const id=localStorage.getItem(storageKey);if(id) {setBusy(true);void poll(id).catch(e=>setMessage(e instanceof Error?e.message:'暂时无法读取建议。')).finally(()=>setBusy(false));}},[poll,storageKey]);
  async function create(event:React.FormEvent<HTMLFormElement>) {
    event.preventDefault();setBusy(true);setMessage('');
    try {const response=await fetch(`/api/v1/plants/${plantId}/adjustments`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({step_index:Number(selected),difficulty})});const data=await response.json();if(!response.ok) throw new Error(data.error?.message || '无法生成建议。');localStorage.setItem(storageKey,data.id);await poll(data.id);}
    catch(e){setMessage(e instanceof Error?e.message:'无法生成建议。');}finally{setBusy(false);}
  }
  async function finish(confirm:boolean) {
    if(!draft)return;setBusy(true);setMessage('');
    try {const steps=edited.split('\n').map(s=>s.trim());if(confirm && (steps.length>5 || steps.some(s=>!s || s.length>500)))throw new Error('请填写一至五条步骤，每条不超过500字且不能留空。');const response=await fetch(`/api/v1/adjustments/${draft.id}/${confirm?'confirm':'discard'}`,{method:'POST',headers:{'Content-Type':'application/json'},...(confirm?{body:JSON.stringify({steps})}:{})});const data=await response.json();if(!response.ok) throw new Error(data.error?.message || '操作失败。');localStorage.removeItem(storageKey);setDraft(null);setDifficulty('');setSelected('');if(confirm){await onChanged();window.dispatchEvent(new Event('bloomate-progress'));}setMessage(confirm?'计划已更新。':'建议已放弃，原计划保持不变。');}
    catch(e){setMessage(e instanceof Error?e.message:'操作失败，请重试。');}finally{setBusy(false);}
  }
  return <div><details><summary>调整一个未完成步骤</summary>{draft ? <div><p>原步骤：{draft.original_text}</p><label>调整建议（可编辑，每行一条）<textarea value={edited} maxLength={2500} onChange={e=>setEdited(e.target.value)}/></label><p className="note">可拆为一至五条；其他步骤及已完成记录保留，原日期只给第一条。</p><button type="button" disabled={busy || !edited.trim()} onClick={()=>void finish(true)}>确认调整</button> <button type="button" disabled={busy} onClick={()=>void finish(false)}>放弃建议</button></div> : <form onSubmit={create}><label>选择未完成步骤<select value={selected} required onChange={e=>setSelected(e.target.value)}><option value="">请选择</option>{actions.filter(a=>!a.completed && !a.cancelled).map(a=><option key={a.index} value={a.index}>{a.text}</option>)}</select></label><label>遇到了什么困难？<textarea required maxLength={1000} value={difficulty} onChange={e=>setDifficulty(e.target.value)} placeholder="例如：这个步骤太耗时"/></label><button type="submit" disabled={busy || !actions.some(a=>!a.completed && !a.cancelled)}>{busy?'正在生成建议…':'生成调整建议'}</button></form>}</details>{message && <p role="status">{message}</p>}</div>;
}
type HabitStage = {start_date:string; end_date:string; timezone:string; weekdays:number[]; completion_standard:string; today:string;status:'upcoming'|'active'|'review_due'|'ended'};
type Occurrence = {date:string; completed:boolean; recorded_at:string|null; is_backfill:boolean; paused:boolean};
type PauseState = {paused:boolean; since:string|null; end_date:string|null; future_days:number|null; future_dates:string[]; today:string;threshold:number|null;completed:number|null;achieved:boolean};
type ScheduleProposal = {id:string; status:string; before:{start_date?:string;end_date:string; weekdays:number[]}; after:{start_date?:string;end_date:string; weekdays:number[]; effective_date:string; future_count:number;includes_today?:boolean;threshold?:number|null;completed?:number|null}};
const weekdayNames=['周一','周二','周三','周四','周五','周六','周日'];
function beijingToday() {
  const parts=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Shanghai',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());
  const value=(type:string)=>parts.find(part=>part.type===type)?.value || '';
  return `${value('year')}-${value('month')}-${value('day')}`;
}

function HabitAdvice({plantId}:{plantId:string}) {
  const [difficulty,setDifficulty]=useState('');const [advice,setAdvice]=useState('');const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');
  const storageKey=`bloomate-habit-advice-${plantId}`;
  const poll=useCallback(async(id:string)=>{for(let i=0;i<75;i++){const r=await fetch(`/api/v1/habit-advice/${id}`);const d=await r.json();if(!r.ok)throw new Error('无法读取习惯建议。');if(d.status==='error'){localStorage.removeItem(storageKey);throw new Error(d.error?.message || '建议生成失败。');}if(d.status==='done'){setAdvice(d.suggestion);return;}await new Promise(resolve=>setTimeout(resolve,1000));}throw new Error('建议仍在生成，刷新后可继续查看。');},[storageKey]);
  useEffect(()=>{const id=localStorage.getItem(storageKey);if(id){setBusy(true);void poll(id).catch(e=>setMessage(e instanceof Error?e.message:'无法读取建议。')).finally(()=>setBusy(false));}},[poll,storageKey]);
  async function create(event:React.FormEvent<HTMLFormElement>){event.preventDefault();setBusy(true);setMessage('');try{const r=await fetch(`/api/v1/plants/${plantId}/habit-advice`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({difficulty})});const d=await r.json();if(!r.ok)throw new Error(d.error?.message || '无法生成建议。');localStorage.setItem(storageKey,d.id);await poll(d.id);}catch(e){setMessage(e instanceof Error?e.message:'无法生成建议。');}finally{setBusy(false);}}
  return <div><details><summary>遇到困难，问问园丁</summary><form onSubmit={create}><label>遇到了什么困难？<textarea required maxLength={1000} value={difficulty} onChange={e=>setDifficulty(e.target.value)} placeholder="例如：最近只有每周三天有时间"/></label><button type="submit" disabled={busy}>{busy?'正在生成建议…':'生成习惯建议'}</button></form>{advice && <div><label>园丁建议（可编辑，仅供参考）<textarea value={advice} maxLength={500} onChange={e=>setAdvice(e.target.value)}/></label><p className="note">建议不会自动修改周期；如需调整，请在下方预览并确认。编辑文字不会保存。</p></div>}</details>{message && <p role="status">{message}</p>}</div>;
}
type Growth = {counts:{completed:number;total:number}|null;threshold:number|null;achieved:boolean;eligible:boolean;progress_percent:number|null};

function FlowerArt({stage,species,count}:{stage:number;species?:FlowerSpecies|null;count:number}) {
  if (species) {
    const phase=stage===0?'seed':stage<=2?'sprout':stage===3?'leaf':stage===4?'bud':'bloom';
    return <Image key={`${species}-${phase}-${count}`} className="flower-photo plant-growing" src={`/flowers/${species}-${phase}.png`} alt="" width={240} height={330} sizes="(max-width: 600px) 120px, 210px"/>;
  }
  return <svg viewBox="0 0 200 190" aria-hidden="true"><ellipse cx="100" cy="169" rx="67" ry="10" fill="#dce8d6"/><circle cx="100" cy="78" r="65" fill="#f4f8e9"/>{stage===0 ? <ellipse cx="100" cy="125" rx="19" ry="25" transform="rotate(28 100 125)" fill="#b88b5f"/> : <g className="plant-growing"><path d="M100 132V76" fill="none" stroke="#527d50" strokeWidth="5"/><path d="M99 112C80 112 73 102 72 90c16 0 27 8 27 22Z" fill="#8caf73"/><path d="M101 102c2-20 13-28 27-29 0 16-10 28-27 29Z" fill="#6d9d63"/></g>}<path d="M48 135h104l-11 29c-2 5-6 8-12 8H71c-6 0-10-3-12-8Z" fill="#c98363"/><path d="M45 132c0-4 3-7 7-7h96c4 0 7 3 7 7s-3 7-7 7H52c-4 0-7-3-7-7Z" fill="#d99b78"/></svg>;
}

type CollectionItem={id:string;plant_id:string;kind:'habit'|'goal';title:string;stage_number:number;species:FlowerSpecies|null;completed_at:string|null;changed:boolean;details:{start_date?:string;end_date?:string;completion_standard?:string;completed?:number;threshold?:number;summary?:string;steps?:string[];outcome?:string}};
function CollectionGallery({onOpenPlant}:{onOpenPlant:(id:string)=>void}) {
  const [items,setItems]=useState<CollectionItem[]|null>(null);const [error,setError]=useState('');
  const load=useCallback(async()=>{const r=await fetch('/api/v1/collections');if(!r.ok)throw new Error();setItems((await r.json()).collections);setError('');},[]);
  useEffect(()=>{const refresh=()=>void load().catch(()=>setError('收藏暂时无法读取。'));refresh();window.addEventListener('bloomate-progress',refresh);return()=>window.removeEventListener('bloomate-progress',refresh);},[load]);
  return <section className="card collection-gallery"><div className="section-heading"><div><span className="eyebrow">YOUR COLLECTION</span><h2>我的收藏</h2><p className="muted">每一朵花，都记录着你完成过的阶段。</p></div>{items && <span className="count-badge">{items.length}</span>}</div>{error && <p role="status">{error}</p>}{!items&&!error?<p>正在读取收藏…</p>:items?.length===0?<div className="today-empty"><span aria-hidden="true">✿</span><strong>这里还没有收藏</strong><p>完成一个目标或习惯阶段，花就会来到这里。</p></div>:<div className="collection-grid">{items?.map(item=><details key={`${item.kind}-${item.id}`} className="collection-card"><summary><span className="collection-art" aria-hidden="true"><FlowerArt stage={5} species={item.species} count={0}/></span><span className="collection-card-copy"><strong>{item.species?flowerNames[item.species]:'花种未记录'}</strong><span>{item.title}</span><small>{item.kind==='habit'?'习惯':'目标'} · 第 {item.stage_number} 阶段</small><small>{item.completed_at?`收藏于 ${item.completed_at.slice(0,10)}`:'收藏日期未记录'}</small>{item.changed && <small>记录后来有更正</small>}<span className="collection-link">查看阶段记录 ↓</span></span></summary><div className="collection-details">{item.details.summary && <p>{item.details.summary}</p>}{item.kind==='habit' && <><p>{item.details.start_date} 至 {item.details.end_date}</p><p>完成 {item.details.completed} / {item.details.threshold} 次 · {item.details.completion_standard}</p></>}{item.details.steps && <ul>{item.details.steps.map((step,i)=><li key={i}>{step}</li>)}</ul>}{item.details.outcome && <p>{item.details.outcome}</p>}{item.changed && <p>以上为收藏时的成果，记录后来有更正。</p>}<button type="button" onClick={()=>onOpenPlant(item.plant_id)}>查看这株植物</button></div></details>)}</div>}</section>;
}

function FlowerPicker({value,onChange}:{value:FlowerSpecies;onChange:(value:FlowerSpecies)=>void}) {
  return <div className="flower-picker" role="group" aria-label="选择花种">{(Object.keys(flowerNames) as FlowerSpecies[]).map(f=><button type="button" key={f} className={value===f?'flower-option active':'flower-option'} aria-pressed={value===f} onClick={()=>onChange(f)}><span aria-hidden="true"><FlowerArt stage={5} species={f} count={0}/></span><strong>{flowerNames[f]}</strong></button>)}</div>;
}

function TodayPlant({plants,today,gardenStatus,onReloadGarden,onOpenPlant}:{plants:Plant[];today:Today;gardenStatus:'loading'|'ready'|'error';onReloadGarden:()=>void;onOpenPlant:(id:string)=>void}) {
  const action=today.habits_today[0] ?? today.goals_today[0];
  const plant=plants.find(p=>p.id===action?.plant_id) ?? plants[0];
  const [growth,setGrowth]=useState<Growth|null>(null);const [failed,setFailed]=useState(false);
  const load=useCallback(async()=>{if(!plant){setGrowth(null);return;}try{const r=await fetch(`/api/v1/plants/${plant.id}/growth`);if(!r.ok)throw new Error();setGrowth(await r.json());setFailed(false);}catch{setGrowth(null);setFailed(true);}},[plant]);
  useEffect(()=>{void load();window.addEventListener('bloomate-progress',load);return()=>window.removeEventListener('bloomate-progress',load);},[load]);
  if(!plant && gardenStatus!=='ready')return <div className="today-plant today-plant-empty"><span className="eyebrow">YOUR LITTLE GARDEN</span><p>{gardenStatus==='error'?'植物暂时无法读取。':'正在读取植物…'}</p>{gardenStatus==='error' && <button type="button" className="text-button" onClick={onReloadGarden}>重试</button>}</div>;
  if(!plant)return <div className="today-plant today-plant-empty"><span className="eyebrow">YOUR LITTLE GARDEN</span><h2>从一颗种子开始</h2><p>制定一个目标或习惯，让你的花园慢慢长大。</p></div>;
  const count=growth?.counts?.completed ?? 0;const ratio=plant.kind==='goal'?(growth?.progress_percent ?? 0)/100:growth?.counts?.total?count/growth.counts.total:0;
  const thresholds=plant.plan.growth_nodes ?? [14,42,71,85];
  const stage=plant.kind==='habit'&&growth?.achieved||plant.kind==='goal'&&ratio>=1?5:ratio*100>=thresholds[3]?4:ratio*100>=thresholds[2]?3:ratio*100>=thresholds[1]?2:ratio*100>=thresholds[0]?1:0;
  const names=['一颗种子','小芽探出头','小芽长大了','枝叶舒展开','花苞出现了','花开了'];
  return <section className="today-plant"><span className="eyebrow">YOUR LITTLE GARDEN</span><h2>{plant.plan.flower_species?`你的${flowerNames[plant.plan.flower_species]}`:'你的植物'}</h2><p>{plant.title}</p>{growth && <div className="today-plant-art" aria-hidden="true"><FlowerArt stage={stage} species={plant.plan.flower_species} count={count}/></div>}<div className="today-plant-bottom"><strong>{failed?'成长状态暂时无法读取':!growth?'正在读取成长状态…':names[stage]}</strong>{growth?.counts && <p>{plant.kind==='habit'?'已打卡':'已完成'} {count} / {growth.counts.total} {plant.kind==='habit'?'次':'个步骤'}</p>}<button type="button" className="text-button" onClick={()=>onOpenPlant(plant.id)}>看看我的植物 ↗</button>{failed && <button type="button" className="text-button" onClick={()=>void load()}>重试</button>}</div></section>;
}

function PlantPortrait({plantId,kind,nodes,species,completedStages=0,currentCollected=false}: {plantId:string;kind:string;nodes?:number[]|null;species?:FlowerSpecies|null;completedStages?:number;currentCollected?:boolean}) {
  const [growth,setGrowth]=useState<Growth|null>(null); const [error,setError]=useState(false);

  const load=useCallback(async()=>{try {const r=await fetch(`/api/v1/plants/${plantId}/growth`);if(!r.ok)throw new Error();setGrowth(await r.json());setError(false);} catch {setGrowth(null);setError(true);}},[plantId]);
  useEffect(()=>{void load();window.addEventListener('bloomate-progress',load);return()=>window.removeEventListener('bloomate-progress',load);},[load]);
  const count=growth?.counts?.completed ?? 0;
  const ratio=kind==='goal' ? (growth?.progress_percent ?? 0)/100 : growth?.counts?.total ? count/growth.counts.total : 0;
  const thresholds=nodes ?? [14,42,71,85];
  const stage = kind==='habit' && growth?.achieved ? 5 : ratio>=1 && kind==='goal' ? 5 : ratio*100>=thresholds[3] ? 4 : ratio*100>=thresholds[2] ? 3 : ratio*100>=thresholds[1] ? 2 : ratio*100>=thresholds[0] ? 1 : 0;
  const names=['一颗种子','小芽探出头','小芽长大了','枝叶舒展开','花苞出现了','花开了'];
  const description=!growth?.counts ? '设置习惯周期后，每次打卡都能陪植物生长。' : `${kind==='habit'?'已打卡':'已完成'} ${count} / ${growth.counts.total} ${kind==='habit'?'次':'个步骤'}。${stage===5 ? (!species?'请选择花种，查看开花的样子。':kind==='goal'?'阶段已完成。':'阶段已完成。') : kind==='habit' && ratio>=1 ? '达到阶段标准后植物会开花。' : '每完成一次行动，植物都会继续生长。'}`;
  return <section id={`portrait-${plantId}`} className="plant-portrait" aria-label="植物成长状态"><div className="plant-art" aria-hidden="true">{growth && species && completedStages>0 && (completedStages>1 || !currentCollected) ? <div className="continuing-plant"><FlowerArt stage={5} species={species} count={count}/>{Array.from({length:Math.min(2,completedStages-1)},(_,i)=><Image key={i} className={`extra-flower-overlay extra-flower-${i}`} src={`/flowers/${species}-bloom.png`} alt="" width={240} height={330}/>)}{!currentCollected && <Image className="new-bud-overlay" src={`/flowers/${species}-bud.png`} alt="" width={240} height={330}/>}</div> : growth && <FlowerArt stage={currentCollected ? 5 : stage} species={species} count={count}/>}</div><div className="plant-portrait-copy"><span className="eyebrow">{species ? flowerNames[species] : '品种待选择'}</span><h3 aria-live="polite">{error?'成长状态暂时无法读取':!growth?'正在读取成长状态…':!species && stage===5?'选择花种，看看它开花':kind==='habit' && currentCollected && !growth.achieved?'已收藏 · 记录已更正':kind==='habit' && completedStages>0 && !currentCollected && stage<=1?'新阶段的小花苞':names[stage]}</h3>{growth && <p>{description}</p>}<a href={`#growth-${plantId}`} onClick={()=>{const details=document.getElementById(`growth-${plantId}`);if(details instanceof HTMLDetailsElement)details.open=true;}}>查看阶段成长 ↓</a></div></section>;
}

function GrowthCard({plantId,kind}: {plantId:string;kind:string}) {
  const [growth,setGrowth]=useState<Growth|null>(null);const [suggestion,setSuggestion]=useState('');const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');
  const storageKey=`bloomate-growth-suggestion-${plantId}`;
  const load=useCallback(async()=>{const r=await fetch(`/api/v1/plants/${plantId}/growth`);if(!r.ok)throw new Error('成长状态暂时无法读取。');setGrowth(await r.json());},[plantId]);
  const poll=useCallback(async(id:string)=>{for(let i=0;i<75;i++){const r=await fetch(`/api/v1/growth/suggestions/${id}`);const d=await r.json();if(!r.ok)throw new Error('无法读取阶段建议。');if(d.status==='error'){localStorage.removeItem(storageKey);throw new Error(d.error?.message || '建议生成失败。');}if(d.status==='done'){setSuggestion(d.suggestion);return;}await new Promise(resolve=>setTimeout(resolve,1000));}throw new Error('建议仍在生成，刷新后可继续查看。');},[storageKey]);
  useEffect(()=>{void load().catch(()=>setMessage('成长状态暂时无法读取。'));const refresh=()=>{void load().catch(()=>setMessage('成长状态暂时无法读取。'));};window.addEventListener('bloomate-progress',refresh);const id=localStorage.getItem(storageKey);if(id){setBusy(true);void poll(id).catch(e=>setMessage(e instanceof Error?e.message:'无法读取建议。')).finally(()=>setBusy(false));}return()=>window.removeEventListener('bloomate-progress',refresh);},[load,poll,storageKey]);
  async function suggest(){setBusy(true);setMessage('');try{const r=await fetch(`/api/v1/plants/${plantId}/growth/suggestions`,{method:'POST'});const d=await r.json();if(!r.ok)throw new Error(d.error?.message || '无法生成建议。');localStorage.setItem(storageKey,d.id);await poll(d.id);}catch(e){setMessage(e instanceof Error?e.message:'无法生成建议。');}finally{setBusy(false);}}
  async function standard(event:React.FormEvent<HTMLFormElement>){event.preventDefault();const fields=new FormData(event.currentTarget);setBusy(true);setMessage('');try{const r=await fetch(`/api/v1/plants/${plantId}/growth/standard`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({threshold:Number(fields.get('threshold'))})});const d=await r.json();if(!r.ok)throw new Error(d.error?.message || '无法保存标准。');await load();window.dispatchEvent(new Event('bloomate-progress'));setMessage('阶段标准已确认。');}catch(e){setMessage(e instanceof Error?e.message:'无法保存标准。');}finally{setBusy(false);}}

  if(!growth)return <p>正在读取成长状态…</p>;
  if(!growth.counts)return <p>先设置习惯周期，再确认阶段标准。</p>;
  if(kind==='goal')return <div><strong>阶段成长</strong><p>已完成 {growth.counts.completed} / {growth.counts.total} 个步骤。完成全部有效步骤后自动完成这一阶段。</p></div>;
  return <div><strong>阶段成长</strong><p>{growth.achieved?'阶段已达标':'阶段进行中'}</p>{kind==='goal' && growth.progress_percent!==null && <p>计划步骤进度：{growth.progress_percent}%（按暂定份额计算，不代表目标已完成）</p>}<p>已完成 {growth.counts.completed} {kind==='habit'?'次打卡':'个步骤'}{growth.threshold ? `，阶段标准 ${growth.threshold} 次` : '，尚未确认阶段标准'}</p><button type="button" disabled={busy || growth.counts.total===0} onClick={()=>void suggest()}>{busy?'处理中…':'让园丁建议阶段标准'}</button>{suggestion && <p>园丁建议：{suggestion}（仅供参考，由你决定。）</p>}<form onSubmit={standard}><label>阶段需要完成多少次？<input name="threshold" type="number" required min={1} max={growth.counts.total} defaultValue={growth.threshold ?? ''} key={growth.threshold ?? 'new'}/></label><p className="note">可选 1 至 {growth.counts.total} 次；达到标准后自动完成阶段。</p><button type="submit" disabled={busy || growth.counts.total===0}>确认阶段标准</button></form>{message && <p role="status">{message}</p>}</div>;
}

function HabitScheduleEditor({plantId,stage,onChanged}: {plantId:string;stage:HabitStage;onChanged:()=>Promise<void>}) {
  const [days,setDays]=useState(stage.weekdays);const [draft,setDraft]=useState<ScheduleProposal|null>(null);
  const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const storageKey=`bloomate-schedule-${plantId}`;
  useEffect(()=>{const id=localStorage.getItem(storageKey);if(id) void fetch(`/api/v1/habit-schedule-proposals/${id}`).then(async r=>{if(!r.ok)throw new Error();const data:ScheduleProposal=await r.json();if(data.status==='pending')setDraft(data);else localStorage.removeItem(storageKey);}).catch(()=>setMessage('暂时无法读取周期调整。'));},[storageKey]);
  async function propose(event:React.FormEvent<HTMLFormElement>) {
    event.preventDefault();const fields=new FormData(event.currentTarget);setBusy(true);setMessage('');
    try {const response=await fetch(`/api/v1/plants/${plantId}/habit-schedule-proposals`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({start_date:fields.get('start_date') || null,end_date:fields.get('end_date'),weekdays:days})});const data=await response.json();if(!response.ok)throw new Error(data.error?.message || '无法预览周期。');setDraft(data);localStorage.setItem(storageKey,data.id);}
    catch(e){setMessage(e instanceof Error?e.message:'无法预览周期。');}finally{setBusy(false);}
  }
  async function finish(confirm:boolean) {
    if(!draft)return;setBusy(true);setMessage('');
    try {const response=await fetch(`/api/v1/habit-schedule-proposals/${draft.id}/${confirm?'confirm':'discard'}`,{method:'POST'});const data=await response.json();if(!response.ok)throw new Error(data.error?.message || '操作失败。');localStorage.removeItem(storageKey);setDraft(null);if(confirm){await onChanged();window.dispatchEvent(new Event('bloomate-progress'));}setMessage(confirm?'周期已更新。':'已放弃，原周期保持不变。');}
    catch(e){setMessage(e instanceof Error?e.message:'操作失败。');}finally{setBusy(false);}
  }
  return <div><details><summary>调整未来习惯周期</summary>{draft ? <div><p>原周期：{draft.before.start_date ? `${draft.before.start_date} 至 ` : '截至 '}{draft.before.end_date}，{draft.before.weekdays.map(d=>weekdayNames[d]).join('、')}</p><p>新周期：{draft.after.start_date ? `${draft.after.start_date} 至 ` : '截至 '}{draft.after.end_date}，{draft.after.weekdays.map(d=>weekdayNames[d]).join('、')}</p><p>从 {draft.after.effective_date} 起更新，共 {draft.after.future_count} 个计划日{draft.after.includes_today ? '（可能包含今天）' : '（不含今天）'}；历史记录不变。</p>{draft.after.threshold != null && <p>当前阶段标准 {draft.after.threshold} 次，已完成 {draft.after.completed ?? 0} 次；今天与可补签日期请另外核对。</p>}<button type="button" disabled={busy} onClick={()=>void finish(true)}>确认周期调整</button> <button type="button" disabled={busy} onClick={()=>void finish(false)}>放弃周期调整</button></div> : <form onSubmit={propose}>{stage.status==='upcoming' && <label>新的开始日期<input type="date" name="start_date" required min={stage.today} defaultValue={stage.start_date}/><small>周期尚未开始，可以改为今天或之后。</small></label>}<label>新的结束日期<input type="date" name="end_date" required defaultValue={stage.end_date}/></label><fieldset><legend>新的每周计划日</legend>{weekdayNames.map((name,i)=><label key={i}><input type="checkbox" checked={days.includes(i)} onChange={e=>setDays(old=>e.target.checked?[...old,i]:old.filter(d=>d!==i))}/>{name}</label>)}</fieldset><p className="note">已开始的周期只影响未来日期；尚未开始的周期可预览调整开始日期。完成标准和时区不变。</p><button type="submit" disabled={busy || !days.length}>预览周期调整</button></form>}</details>{message && <p role="status">{message}</p>}</div>;
}

function HabitActions({plantId,paused}: {plantId:string;paused:boolean}) {
  const [stage, setStage] = useState<HabitStage|null>(null);
  const [occurrences, setOccurrences] = useState<Occurrence[]>([]);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(''); const [feedback,setFeedback]=useState('');
  const [standard, setStandard] = useState(''); const [days, setDays] = useState([0,1,2,3,4,5,6]);
  const [suggestedStart] = useState(beijingToday);
  const [startDate,setStartDate]=useState(suggestedStart);const [endDate,setEndDate]=useState('');const [growthThreshold,setGrowthThreshold]=useState<number|null>(null);
  const startMs=Date.parse(`${startDate}T00:00:00Z`),endMs=Date.parse(`${endDate}T00:00:00Z`);
  let plannedDays=0;if(Number.isFinite(startMs) && Number.isFinite(endMs) && endMs>=startMs && endMs-startMs<=3660*86400000){for(let t=startMs;t<=endMs;t+=86400000)if(days.includes((new Date(t).getUTCDay()+6)%7))plannedDays++;}
  const load = useCallback(async () => {
    const response = await fetch(`/api/v1/plants/${plantId}/habit-stage`);
    if (!response.ok) throw new Error('习惯周期暂时无法读取。');
    const data = await response.json(); setStage(data.stage); setOccurrences(data.occurrences);
  }, [plantId]);
  useEffect(() => {const refresh=()=>void load().catch(() => setError('习惯周期暂时无法读取，请刷新重试。')).finally(() => setLoading(false));refresh();window.addEventListener('bloomate-progress',refresh);return()=>window.removeEventListener('bloomate-progress',refresh);}, [load,paused]);
  async function create(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault(); const fields = new FormData(event.currentTarget); setBusy(true); setError('');
    try {
      const response = await fetch(`/api/v1/plants/${plantId}/habit-stage`, {method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({start_date:fields.get('start_date'),end_date:fields.get('end_date'),timezone:'Asia/Shanghai',weekdays:days,completion_standard:standard,growth_threshold:growthThreshold ?? plannedDays})});
      const data = await response.json(); if (!response.ok) throw new Error(data.error?.message || '无法设置周期，请检查日期和星期。');
      await load(); window.dispatchEvent(new Event('bloomate-progress'));
    } catch (e) {setError(e instanceof Error ? e.message : '设置失败，请重试。');} finally {setBusy(false);}
  }
  async function toggle(item:Occurrence) {
    setBusy(true); setError('');
    try {
      const response = await fetch(`/api/v1/plants/${plantId}/habit-occurrences/${item.date}`, {method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({completed:!item.completed,performed:!item.completed})});
      const data = await response.json(); if (!response.ok) throw new Error(data.error?.message || '保存失败。');
      setOccurrences(current => current.map(entry => entry.date === data.date ? data : entry)); setFeedback(data.completed?'已记录，你的植物正在生长。':'已撤销，植物状态已更新。'); window.dispatchEvent(new Event('bloomate-progress'));
    } catch (e) {setError(e instanceof Error ? e.message : '保存失败，请重试。');} finally {setBusy(false);}
  }
  if (loading) return <p>正在读取习惯周期…</p>;
  return <div><strong>习惯打卡</strong>{feedback && <p role="status">{feedback} <a href={`#portrait-${plantId}`}>看看植物 ↑</a></p>}{stage ? <div><p>{stage.start_date} 至 {stage.end_date} · {stage.timezone}</p><p>{stage.status==='ended'?'这个习惯已先结束，历史花朵与记录保留；可以选择继续下一阶段。':stage.status==='review_due'?'周期已到期，等待复盘；不会自动达成成果。':stage.status==='upcoming'?`周期从 ${stage.start_date} 开始，今天暂不能打卡。如需今天开始，展开下方「调整未来习惯周期」并预览确认。`:'周期进行中。'}</p><p>每周计划日：{stage.weekdays.map(day=>weekdayNames[day]).join('、')}</p><p>每次完成标准：{stage.completion_standard}</p>{stage.status==='active' && !occurrences.some(item=>item.date===stage.today) && <p className="note">今天不是计划日，所以没有今天的打卡按钮。</p>}{stage.status==='active' && occurrences.some(item=>item.date===stage.today && item.paused && !item.completed) && <p className="note">今天是暂停日，不能新增打卡。</p>}{occurrences.length ? <ul>{occurrences.map(item => <li key={item.date}>{item.date}{item.is_backfill && item.completed ? '（补签）' : ''}{item.paused ? '（暂停日）' : ''} <button type="button" disabled={busy || (item.paused && !item.completed)} onClick={() => void toggle(item)}>{item.completed ? '已完成，撤销' : item.date === stage.today ? '确认今天已完成' : '确认当天已完成并补签'}</button></li>)}</ul> : <p>今天和最近三天没有计划日。</p>}<p className="note">补签仅用于实际做过、但忘记记录的行动。</p><HabitAdvice plantId={plantId}/><HabitScheduleEditor key={`${stage.end_date}-${stage.weekdays.join(',')}`} plantId={plantId} stage={stage} onChanged={load}/></div> : <form onSubmit={create}><p>设置开始日期、结束日期和计划日，再开始打卡。日期按北京时间计算；确认后可预览并调整未来计划日。</p><label>开始日期<input name="start_date" type="date" required value={startDate} onChange={e=>{setStartDate(e.target.value);setGrowthThreshold(null);}}/></label><label>结束日期<input name="end_date" type="date" required value={endDate} onChange={e=>{setEndDate(e.target.value);setGrowthThreshold(null);}}/></label><label>每次怎样算完成？<input required maxLength={200} value={standard} onChange={e=>setStandard(e.target.value)} placeholder="例如：读满20分钟"/></label><fieldset><legend>每周计划日</legend>{weekdayNames.map((name,index)=><label key={index}><input type="checkbox" checked={days.includes(index)} onChange={e=>{setGrowthThreshold(null);setDays(current=>e.target.checked?[...current,index]:current.filter(n=>n!==index));}}/>{name}</label>)}</fieldset><label>阶段完成标准（次数）<input type="number" min={1} max={plannedDays || 1} required value={growthThreshold ?? (plannedDays || '')} onChange={e=>setGrowthThreshold(e.target.value ? Number(e.target.value) : null)}/></label><p className="note">{plannedDays ? `这个周期有 ${plannedDays} 个计划日；默认建议完成全部，你可以修改。达到后花会开放。` : '选择日期和计划日后显示建议次数。'}</p><button type="submit" disabled={busy || days.length===0 || plannedDays===0}>确认习惯周期</button></form>}{error && <p role="status">{error}</p>}</div>;
}

type HabitCollection = {stage_id:string;confirmed_at:string|null;changed:boolean;active:boolean;current_entries:{action_date:string;completed:boolean;enabled:boolean}[];snapshot:{title:string;start_date:string;end_date:string;threshold:number;completed:number;completion_standard:string;flower_species?:FlowerSpecies|null}};
type NextHabitProposal = {id:string;status:string;after:{start_date:string;end_date:string;timezone:string;weekdays:number[];completion_standard:string;growth_threshold:number}};
function HabitJourney({plantId,species,onHistory}:{plantId:string;species?:FlowerSpecies|null;onHistory:(n:number,current:boolean)=>void}) {
  const [history,setHistory]=useState<HabitCollection[]>([]);const [ended,setEnded]=useState(false);const [achieved,setAchieved]=useState(false);const [stage,setStage]=useState<HabitStage|null>(null);const [draft,setDraft]=useState<NextHabitProposal|null>(null);const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const [days,setDays]=useState<number[]>([0,1,2,3,4,5,6]);const [showForm,setShowForm]=useState(false);const key=`bloomate-next-habit-${plantId}`;
  const [nextStart,setNextStart]=useState('');const [nextEnd,setNextEnd]=useState('');const [nextStandard,setNextStandard]=useState<string|null>(null);const [nextThreshold,setNextThreshold]=useState<string|null>(null);
  const [notice,setNotice]=useState<string|null>(null);
  const loadNotice=useCallback(async()=>{const r=await fetch(`/api/v1/plants/${plantId}/completion-notice`);if(!r.ok)throw new Error();const d=await r.json();setNotice(d.status);if(d.status==='continue')setShowForm(true);},[plantId]);
  useEffect(()=>{void loadNotice().catch(()=>setMessage('完成提示暂时无法读取。'));const refresh=()=>void loadNotice().catch(()=>setMessage('完成提示暂时无法读取。'));window.addEventListener('bloomate-progress',refresh);return()=>window.removeEventListener('bloomate-progress',refresh);},[loadNotice]);
  async function chooseNotice(choice:'finish'|'continue'){setBusy(true);try{const r=await fetch(`/api/v1/plants/${plantId}/completion-notice`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({choice})});const d=await r.json();if(!r.ok)throw new Error(d.error?.message||'暂时无法保存选择。');setNotice(d.status);if(choice==='continue'){setShowForm(true);setTimeout(()=>document.getElementById(`next-habit-${plantId}`)?.scrollIntoView({block:'start',behavior:'smooth'}),50);}else setMessage('当前阶段已完成，花朵和记录已收藏。');window.dispatchEvent(new Event('bloomate-progress'));}catch(e){setMessage(e instanceof Error?e.message:'暂时无法保存选择。');}finally{setBusy(false);}}
  const load=useCallback(async()=>{try{const [a,b,c]=await Promise.all([fetch(`/api/v1/plants/${plantId}/habit-stages`),fetch(`/api/v1/plants/${plantId}/growth`),fetch(`/api/v1/plants/${plantId}/habit-stage`)]);if(!a.ok||!b.ok||!c.ok)throw new Error();const list=await a.json();setHistory(list.collections);onHistory(list.collections.length,list.collections.some((h:HabitCollection)=>h.active));setEnded(list.ended);setAchieved((await b.json()).achieved);setStage((await c.json()).stage);}catch{setMessage('阶段记录暂时无法读取。');}},[plantId,onHistory]);
  useEffect(()=>{void load();window.addEventListener('bloomate-progress',load);const id=localStorage.getItem(key);if(id)void fetch(`/api/v1/habit-next-proposals/${id}`).then(async r=>{if(!r.ok)throw new Error();const p:NextHabitProposal=await r.json();if(p.status==='pending'){setNextStart(p.after.start_date);setNextEnd(p.after.end_date);setNextStandard(p.after.completion_standard);setNextThreshold(String(p.after.growth_threshold));setDays(p.after.weekdays);setShowForm(true);setDraft(p);}else localStorage.removeItem(key);}).catch(()=>setMessage('待确认的阶段计划暂时无法读取。'));return()=>window.removeEventListener('bloomate-progress',load);},[load,key]);
  async function end(){setBusy(true);setMessage('');try{const r=await fetch(`/api/v1/plants/${plantId}/habit-end`,{method:'POST'});const d=await r.json();if(!r.ok)throw new Error(d.error?.message||'暂时无法结束。');setMessage('这一阶段已结束，历史花朵会保留。');await load();window.dispatchEvent(new Event('bloomate-progress'));}catch(e){setMessage(e instanceof Error?e.message:'暂时无法结束。');}finally{setBusy(false);}}
  async function preview(event:React.FormEvent<HTMLFormElement>){event.preventDefault();if(!stage)return;setMessage('');const start=nextStart||tomorrow;const standard=(nextStandard??stage.completion_standard).trim();const threshold=nextThreshold===null?plannedDays:Number(nextThreshold);if(!start||start<tomorrow){setMessage('开始日期请选择明天或以后的日期。');return;}if(!nextEnd||nextEnd<start){setMessage('请选择不早于开始日期的结束日期。');return;}if(!standard){setMessage('请填写每次的完成标准。');return;}if(!days.length||plannedDays===0){setMessage('日期范围内没有选中的计划日，请调整日期或勾选对应星期。');return;}if(!Number.isInteger(threshold)||threshold<1||threshold>plannedDays){setMessage(`阶段完成次数请填写 1 到 ${plannedDays} 次。`);return;}setBusy(true);try{const r=await fetch(`/api/v1/plants/${plantId}/next-stage-proposals`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({start_date:start,end_date:nextEnd,timezone:stage.timezone,weekdays:days,completion_standard:standard,growth_threshold:threshold})});const d=await r.json();if(!r.ok)throw new Error(d.error?.message||'无法开始新阶段。');setDraft(d);localStorage.setItem(key,d.id);}catch(e){setMessage(e instanceof Error?e.message:'无法开始新阶段。');}finally{setBusy(false);}}
  async function correct(stageId:string,day:string,completed:boolean){if(!window.confirm(completed?'确认这一天确实完成了吗？':'确认撤销这一天的完成记录吗？收藏会保留并标注更正。'))return;setBusy(true);setMessage('');try{const r=await fetch(`/api/v1/habit-stages/${stageId}/occurrences/${day}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({completed,performed:completed})});const d=await r.json();if(!r.ok)throw new Error(d.error?.message||'无法更正记录。');await load();setMessage('记录已更正，原有收藏保留。');}catch(e){setMessage(e instanceof Error?e.message:'无法更正记录。');}finally{setBusy(false);}}
  async function finish(confirm:boolean){if(!draft)return;setBusy(true);setMessage('');try{const r=await fetch(`/api/v1/habit-next-proposals/${draft.id}/${confirm?'confirm':'discard'}`,{method:'POST'});const d=await r.json();if(!r.ok)throw new Error(d.error?.message||'操作失败。');localStorage.removeItem(key);setDraft(null);setShowForm(!confirm);setMessage(confirm?'新阶段已开始，原有花朵与记录保留。':'可以继续修改，原计划不变。');await load();if(confirm)window.dispatchEvent(new Event('bloomate-progress'));}catch(e){setMessage(e instanceof Error?e.message:'操作失败。');}finally{setBusy(false);}}
  const tomorrow=stage ? new Date(Date.parse(`${stage.today}T00:00:00Z`)+86400000).toISOString().slice(0,10) : '';
  const fromMs=Date.parse(`${nextStart||tomorrow}T00:00:00Z`),toMs=Date.parse(`${nextEnd}T00:00:00Z`);let plannedDays=0;if(Number.isFinite(fromMs)&&Number.isFinite(toMs)&&toMs>=fromMs&&toMs-fromMs<=3660*86400000){for(let t=fromMs;t<=toMs;t+=86400000)if(days.includes((new Date(t).getUTCDay()+6)%7))plannedDays++;}
  return <details className="plant-block" open={history.length>0 || showForm || notice==='pending'}><summary>阶段花朵与继续 <span>回看成果、开始下一阶段</span></summary>{notice==='pending' && <div className="completion-overlay"><div className="completion-dialog" role="dialog" aria-modal="true" aria-labelledby={`completion-title-${plantId}`}><h2 id={`completion-title-${plantId}`}>这一阶段完成了，花开了！</h2><p>这朵花和你的打卡记录会留在花园里。接下来你想怎么做？</p><div><button type="button" autoFocus disabled={busy} onClick={()=>void chooseNotice('finish')}>完成</button> <button type="button" disabled={busy} onClick={()=>void chooseNotice('continue')}>继续下一阶段</button></div>{message && <p role="alert">{message}</p>}</div></div>}{history.length>0 ? <><div className="habit-flowers">{history.slice(-3).map(h=><div key={h.stage_id} className="habit-flower"><FlowerArt stage={5} species={h.snapshot.flower_species ?? species} count={0}/><span>已收藏</span></div>)}{!history.some(h=>h.active) && stage && <div className="habit-flower"><FlowerArt stage={4} species={species} count={0}/><span>新阶段</span></div>}</div><p>已完成 {history.length} 个阶段{ended?' · 已先结束，可再选择继续':''}</p>{history.map((h,i)=><details key={h.stage_id}><summary>第 {i+1} 阶段 · {h.snapshot.start_date} 至 {h.snapshot.end_date}</summary><p>确认时完成 {h.snapshot.completed} / {h.snapshot.threshold} 次 · {h.snapshot.completion_standard}</p><p>{h.confirmed_at ? `确认时间：${h.confirmed_at.slice(0,10)}` : '确认时间未记录'}</p>{h.changed && <p>记录后来有更正，以上为确认时的收藏。</p>}{!h.active && <details><summary>查看或更正历史打卡</summary><ul>{h.current_entries.filter(e=>e.enabled && e.action_date<=beijingToday()).map(e=><li key={e.action_date}>{e.action_date} · {e.completed?'已完成':'未完成'} <button type="button" disabled={busy} onClick={()=>void correct(h.stage_id,e.action_date,!e.completed)}>{e.completed?'撤销完成':'确认补记'}</button></li>)}</ul></details>}</details>)}</> : <p>达到阶段标准后，这里会保留对应的花朵与记录。</p>}{(achieved||ended||history.some(h=>h.active)) && !draft && <div>{!ended && <button type="button" disabled={busy} onClick={()=>void end()}>先到这里</button>} <button type="button" disabled={busy} onClick={()=>setShowForm(v=>!v)}>{ended?'继续这个习惯':'继续下一阶段'}</button></div>}{showForm && stage && <form id={`next-habit-${plantId}`} onSubmit={preview} noValidate><p>填写下一阶段，开始前会请你确认。</p><label>开始日期<input name="start_date" type="date" min={tomorrow} value={nextStart||tomorrow} onChange={e=>{setNextStart(e.target.value);setNextThreshold(null);}} required/></label><label>结束日期<input name="end_date" type="date" min={nextStart||tomorrow} value={nextEnd} onChange={e=>{setNextEnd(e.target.value);setNextThreshold(null);}} required/></label><label>每次完成标准<input name="completion_standard" maxLength={200} value={nextStandard??stage.completion_standard} onChange={e=>setNextStandard(e.target.value)} required/></label><fieldset><legend>每周计划日</legend>{weekdayNames.map((name,i)=><label key={name}><input type="checkbox" checked={days.includes(i)} onChange={e=>{setNextThreshold(null);setDays(old=>e.target.checked?[...old,i]:old.filter(n=>n!==i));}}/>{name}</label>)}</fieldset><label>阶段完成次数<input name="growth_threshold" type="number" min={1} max={plannedDays||1} value={nextThreshold??(plannedDays?String(plannedDays):'')} onChange={e=>setNextThreshold(e.target.value)} required/></label><p className="note">{plannedDays?`这个周期有 ${plannedDays} 个计划日，默认完成全部，也可以修改。`:nextEnd?'所选日期内没有对应的计划日，请调整星期或日期。':'选择结束日期和计划日后，会自动建议完成次数。'}</p>{message && <p role="alert">{message}</p>}<button type="submit" disabled={busy}>开始下一阶段</button></form>}{draft && <div className="completion-overlay"><div className="completion-dialog" role="dialog" aria-modal="true" aria-labelledby={`next-habit-confirm-${plantId}`}><h2 id={`next-habit-confirm-${plantId}`}>确认开始下一阶段？</h2><p>时间：{draft.after.start_date} 至 {draft.after.end_date}</p><p>计划日：{draft.after.weekdays.map(d=>weekdayNames[d]).join('、')}</p><p>每次：{draft.after.completion_standard}</p><p>阶段目标：完成 {draft.after.growth_threshold} 次</p><p>原来的花朵和记录会保留。</p><button type="button" disabled={busy} onClick={()=>void finish(false)}>返回修改</button> <button type="button" autoFocus disabled={busy} onClick={()=>void finish(true)}>确认开始</button>{message && <p role="alert">{message}</p>}</div></div>}{message && <p role="status">{message}</p>}</details>;
}

type GoalStage = {id:string;title:string;steps:string[];states:boolean[];dates:(string|null)[];active:boolean;completed_at:string|null};
type GoalDraft = {id:string;status:string;title:string;steps:string[]};
function GoalJourney({plantId,paused,onActive,onHistory}:{plantId:string;paused:boolean;onActive:(active:boolean)=>void;onHistory:(count:number,current:boolean)=>void}) {
  const [stages,setStages]=useState<GoalStage[]>([]);const [hasCollection,setHasCollection]=useState(false);const [notice,setNotice]=useState<string|null>(null);const [showForm,setShowForm]=useState(false);const [draft,setDraft]=useState<GoalDraft|null>(null);const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const key=`bloomate-next-goal-${plantId}`;
  const generationKey=`bloomate-goal-generation-${plantId}`;const [generatedId,setGeneratedId]=useState<string|null>(null);const [generatedTitle,setGeneratedTitle]=useState('');const [generatedSteps,setGeneratedSteps]=useState('');const [generatedSummary,setGeneratedSummary]=useState('');
  const [durationUnknown,setDurationUnknown]=useState(false);const [minutesUnknown,setMinutesUnknown]=useState(false);const [generatedTime,setGeneratedTime]=useState<{duration_days:number|null;daily_minutes:number|null}>({duration_days:null,daily_minutes:null});
  const pollGeneration=useCallback(async(id:string)=>{for(let i=0;i<75;i++){const r=await fetch(`/api/v1/plans/${id}`);const d=await r.json();if(!r.ok)throw new Error('暂时无法读取园丁建议。');if(d.status==='error'){localStorage.removeItem(generationKey);throw new Error(d.error?.message||'园丁建议生成失败。');}if(d.status==='done'&&d.proposal){if(d.followup_time_required){localStorage.removeItem(generationKey);setGeneratedId(null);setShowForm(true);setMessage('之前的建议没有确认新阶段时间，请重新填写时间或选择不确定，再让园丁制定。');return;}setGeneratedId(id);setGeneratedTitle(d.proposal.title);setGeneratedSteps(d.proposal.steps.join('\n'));setGeneratedSummary(d.proposal.summary);setGeneratedTime(d.followup_time??{duration_days:null,daily_minutes:null});setShowForm(true);return;}await new Promise(resolve=>setTimeout(resolve,1000));}throw new Error('园丁仍在准备建议，刷新后可继续查看。');},[generationKey]);
  useEffect(()=>{const id=localStorage.getItem(generationKey);if(id){setBusy(true);void pollGeneration(id).catch(e=>setMessage(e instanceof Error?e.message:'无法读取园丁建议。')).finally(()=>setBusy(false));}},[generationKey,pollGeneration]);
  const load=useCallback(async()=>{const [a,b,c]=await Promise.all([fetch(`/api/v1/plants/${plantId}/goal-stages`),fetch(`/api/v1/plants/${plantId}/completion-notice`),fetch(`/api/v1/plants/${plantId}/collection`)]);if(!a.ok||!b.ok||!c.ok)throw new Error();const list:GoalStage[]=(await a.json()).stages;const status=(await b.json()).status;const saved=(await c.json()).collection;setStages(list);setNotice(status);setHasCollection(Boolean(saved));onActive(list.some(s=>s.active));onHistory((saved?1:0)+list.filter(s=>s.completed_at).length,Boolean(list.find(s=>s.active)?.completed_at || (!list.some(s=>s.active) && saved)));if(status==='continue')setShowForm(true);},[plantId,onActive,onHistory]);
  useEffect(()=>{const refresh=()=>void load().catch(()=>setMessage('阶段记录暂时无法读取。'));refresh();window.addEventListener('bloomate-progress',refresh);const id=localStorage.getItem(key);if(id)void fetch(`/api/v1/goal-next-proposals/${id}`).then(async r=>{if(!r.ok)throw new Error();const d=await r.json();if(d.status==='pending')setDraft(d);else localStorage.removeItem(key);}).catch(()=>setMessage('待确认的阶段计划暂时无法读取。'));return()=>window.removeEventListener('bloomate-progress',refresh);},[load,key]);
  async function choice(value:'finish'|'continue'){setBusy(true);try{const r=await fetch(`/api/v1/plants/${plantId}/completion-notice`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({choice:value})});const d=await r.json();if(!r.ok)throw new Error(d.error?.message||'保存失败。');setNotice(d.status);setShowForm(value==='continue');if(value==='continue')setTimeout(()=>document.getElementById(`next-goal-${plantId}`)?.scrollIntoView({block:'start',behavior:'smooth'}),50);window.dispatchEvent(new Event('bloomate-progress'));}catch(e){setMessage(e instanceof Error?e.message:'保存失败。');}finally{setBusy(false);}}
  async function generateNext(e:React.FormEvent<HTMLFormElement>){e.preventDefault();setBusy(true);setMessage('');const f=new FormData(e.currentTarget);try{const r=await fetch(`/api/v1/plants/${plantId}/goal-next-generation`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:f.get('title'),details:f.get('details')||'',duration_days:durationUnknown?null:Number(f.get('duration_days')),daily_minutes:minutesUnknown?null:Number(f.get('daily_minutes'))})});const d=await r.json();if(!r.ok)throw new Error(d.error?.message||'无法生成建议。');localStorage.setItem(generationKey,d.id);await pollGeneration(d.id);}catch(e){setMessage(e instanceof Error?e.message:'无法生成建议。');}finally{setBusy(false);}}
  async function confirmGenerated(e:React.FormEvent<HTMLFormElement>){e.preventDefault();if(!generatedId)return;setBusy(true);setMessage('');try{const steps=generatedSteps.split('\n').map(x=>x.trim()).filter(Boolean);if(!steps.length)throw new Error('请至少保留一个步骤。');const r=await fetch(`/api/v1/plants/${plantId}/goal-next-proposals`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({title:generatedTitle,steps,generation_id:generatedId})});const d=await r.json();if(!r.ok)throw new Error(d.error?.message||'无法保存建议。');setDraft(d);localStorage.setItem(key,d.id);const confirm=await fetch(`/api/v1/goal-next-proposals/${d.id}/confirm`,{method:'POST'});const result=await confirm.json();if(!confirm.ok)throw new Error(result.error?.message||'无法开始新阶段。');localStorage.removeItem(key);localStorage.removeItem(generationKey);setGeneratedId(null);setDraft(null);setShowForm(false);setMessage('新阶段已开始，原有花朵和记录保留。');window.dispatchEvent(new Event('bloomate-progress'));}catch(e){setMessage(e instanceof Error?e.message:'无法开始新阶段。');}finally{setBusy(false);}}
  async function resolve(confirm:boolean){if(!draft)return;setBusy(true);try{const r=await fetch(`/api/v1/goal-next-proposals/${draft.id}/${confirm?'confirm':'discard'}`,{method:'POST'});const d=await r.json();if(!r.ok)throw new Error(d.error?.message||'保存失败。');localStorage.removeItem(key);localStorage.removeItem(generationKey);setGeneratedId(null);setDraft(null);setShowForm(false);setMessage(confirm?'新阶段已开始，原有花朵和记录保留。':'已放弃，原计划不变。');window.dispatchEvent(new Event('bloomate-progress'));}catch(e){setMessage(e instanceof Error?e.message:'保存失败。');}finally{setBusy(false);}}
  async function toggle(stage:GoalStage,index:number){setBusy(true);try{const r=await fetch(`/api/v1/goal-stages/${stage.id}/actions/${index}`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({completed:!stage.states[index]})});const d=await r.json();if(!r.ok)throw new Error(d.error?.message||'保存失败。');window.dispatchEvent(new Event('bloomate-progress'));}catch(e){setMessage(e instanceof Error?e.message:'保存失败。');}finally{setBusy(false);}}
  async function schedule(event:React.FormEvent<HTMLFormElement>,stage:GoalStage,index:number){event.preventDefault();const fields=new FormData(event.currentTarget);setBusy(true);setMessage('');try{const r=await fetch(`/api/v1/goal-stages/${stage.id}/actions/${index}/date`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({due_date:fields.get('due_date')||null})});const d=await r.json();if(!r.ok)throw new Error(d.error?.message||'日期保存失败。');setMessage(d.due_date?'日期已保存。':'日期已清空。');window.dispatchEvent(new Event('bloomate-progress'));}catch(e){setMessage(e instanceof Error?e.message:'日期保存失败。');}finally{setBusy(false);}}
  const active=stages.find(s=>s.active);
  return <section className="plant-block">{notice==='pending' && <div className="completion-overlay"><div className="completion-dialog" role="dialog" aria-modal="true" aria-labelledby={`goal-completion-${plantId}`}><h2 id={`goal-completion-${plantId}`}>这一阶段完成了，花开了！</h2><p>这朵花和你的计划记录会留在花园里。接下来你想怎么做？</p><button type="button" autoFocus disabled={busy} onClick={()=>void choice('finish')}>完成</button> <button type="button" disabled={busy} onClick={()=>void choice('continue')}>继续下一阶段</button>{message && <p role="alert">{message}</p>}</div></div>}{active && <div><strong>当前阶段：{active.title}</strong><ul>{active.steps.map((step,i)=><li key={i}>{step} <button type="button" disabled={busy||(paused&&!active.states[i])} onClick={()=>void toggle(active,i)}>{active.states[i]?'已完成，撤销':'标记完成'}</button> <details className="step-tools"><summary>{active.dates[i] ? `日期：${active.dates[i]}` : '安排日期'}</summary><form onSubmit={event=>void schedule(event,active,i)}><label>计划日期<input type="date" name="due_date" defaultValue={active.dates[i]||''} key={active.dates[i]||'empty'}/></label><button type="submit" disabled={busy}>保存日期</button><span className="note">清空日期并保存可以取消安排。</span></form></details></li>)}</ul>{active.completed_at && !active.states.every(Boolean) && <p>记录后来有更正，原有收藏保留。</p>}</div>}{stages.filter(s=>!s.active).map(s=><details key={s.id}><summary>已收藏阶段：{s.title}</summary><ul>{s.steps.map((step,i)=><li key={i}>{step}</li>)}</ul></details>)}{(notice || (!active && hasCollection)) && notice!=='pending' && !draft && <button type="button" disabled={busy} onClick={()=>setShowForm(v=>!v)}>继续下一阶段</button>}{showForm&&!draft&&!generatedId && <form id={`next-goal-${plantId}`} onSubmit={generateNext}><p>告诉园丁接下来想做什么，园丁会结合上一阶段帮你拆分行动。</p><label>下一阶段想做什么？<input name="title" maxLength={100} required placeholder="例如：优化简历"/></label><label>希望几天完成？<input type="number" name="duration_days" min={1} max={3650} required={!durationUnknown} disabled={durationUnknown} placeholder="例如：3 天"/></label><label><input type="checkbox" checked={durationUnknown} onChange={e=>setDurationUnknown(e.target.checked)}/>不确定，让园丁建议完成时间</label><label>每天大概能花多少分钟？<input type="number" name="daily_minutes" min={1} max={720} required={!minutesUnknown} disabled={minutesUnknown} placeholder="例如：20 分钟"/></label><label><input type="checkbox" checked={minutesUnknown} onChange={e=>setMinutesUnknown(e.target.checked)}/>不确定，让园丁建议每天的时间</label><label>还有什么需要园丁知道的？（选填）<textarea name="details" maxLength={1000} placeholder="例如：想突出项目经历"/></label><p className="note">生成时会把原目标、已有计划、原先提供的背景和本次补充发送给模型服务商；已授权的园丁记忆也可能被使用。生成可能产生模型调用费用。</p><button type="submit" disabled={busy}>{busy?'园丁正在制定…':'让园丁制定下一阶段'}</button></form>}{showForm&&!draft&&generatedId && <form id={`next-goal-${plantId}`} onSubmit={confirmGenerated}><strong>园丁为你建议的下一阶段</strong><p className="note">{generatedTime.duration_days===null?'完成周期由园丁建议，尚未由你确定':`你希望 ${generatedTime.duration_days} 天完成`}；{generatedTime.daily_minutes===null?'每天投入时间由园丁建议，尚未由你确定':`你每天最多投入 ${generatedTime.daily_minutes} 分钟`}。</p><p>{generatedSummary}</p><label>阶段名称<input value={generatedTitle} maxLength={200} onChange={e=>setGeneratedTitle(e.target.value)} required/></label><label>行动步骤（每行一条，可直接修改）<textarea value={generatedSteps} onChange={e=>setGeneratedSteps(e.target.value)} required/></label><p>确认后才会开始新阶段；原有花朵和记录保留。</p><button type="submit" disabled={busy}>确认并开始</button> <button type="button" disabled={busy} onClick={()=>{localStorage.removeItem(generationKey);setGeneratedId(null);setMessage('可以修改需求后让园丁重新制定。');}}>重新制定</button> <button type="button" disabled={busy} onClick={()=>{localStorage.removeItem(generationKey);setGeneratedId(null);setShowForm(false);setMessage('已放弃建议，原计划不变。');}}>暂不开始</button></form>}{draft && <div><strong>新阶段：{draft.title}</strong><ul>{draft.steps.map((s,i)=><li key={i}>{s}</li>)}</ul><button type="button" disabled={busy} onClick={()=>void resolve(true)}>确认新阶段</button> <button type="button" disabled={busy} onClick={()=>void resolve(false)}>放弃</button></div>}{message && <p role="status">{message}</p>}</section>;
}

function GoalActions({plantId,paused}: {plantId: string;paused:boolean}) {
  const [actions, setActions] = useState<GoalAction[]>([]);
  const [loading, setLoading] = useState(true);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState(''); const [feedback,setFeedback]=useState('');
  const [suggestedDate,setSuggestedDate] = useState('');
  const refresh = useCallback(async () => {const r=await fetch(`/api/v1/plants/${plantId}/actions`);if(!r.ok)throw new Error('无法读取计划步骤。');const data=await r.json();setActions(data.actions);},[plantId]);
  useEffect(() => {
    let active = true;
    fetch(`/api/v1/plants/${plantId}/actions`).then(async r => {
      if (!r.ok) throw new Error();
      const data = await r.json(); if (active) setActions(data.actions);
    }).catch(() => {if (active) setError('计划步骤暂时无法读取，请刷新重试。');}).finally(() => {if (active) setLoading(false);});
    return () => {active = false;};
  }, [plantId]);
  async function toggle(action: GoalAction) {
    setBusy(true); setError('');
    try {
      const response = await fetch(`/api/v1/plants/${plantId}/actions/${action.index}`, {method:'PUT', headers:{'Content-Type':'application/json'}, body:JSON.stringify({completed:!action.completed})});
      if (!response.ok) throw new Error();
      const updated: GoalAction = await response.json();
      setActions(current => current.map(item => item.index === updated.index ? updated : item)); setFeedback(updated.completed?'已完成，你的植物正在生长。':'已撤销，植物状态已更新。'); window.dispatchEvent(new Event('bloomate-progress'));
    } catch {setError('保存失败，请稍后重试。');}
    finally {setBusy(false);}
  }
  async function schedule(event:React.FormEvent<HTMLFormElement>, action:GoalAction) {
    event.preventDefault();const fields=new FormData(event.currentTarget);setBusy(true);setError('');
    try {const response=await fetch(`/api/v1/plants/${plantId}/actions/${action.index}/date`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({due_date:fields.get('due_date') || null})});if(!response.ok)throw new Error();const updated:GoalAction=await response.json();setActions(current=>current.map(item=>item.index===updated.index?updated:item));window.dispatchEvent(new Event('bloomate-progress'));}
    catch{setError('日期保存失败，请稍后重试。');}finally{setBusy(false);}
  }
  async function manual(event:React.FormEvent<HTMLFormElement>,index:number|null) {
    event.preventDefault();const form=event.currentTarget;const fields=new FormData(form);setBusy(true);setError('');
    try{const response=await fetch(index===null?`/api/v1/plants/${plantId}/actions`:`/api/v1/plants/${plantId}/actions/${index}/text`,{method:index===null?'POST':'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({text:fields.get('text')})});const data=await response.json();if(!response.ok)throw new Error(data.error?.message || '保存失败。');await refresh();if(index===null)form.reset();window.dispatchEvent(new Event('bloomate-progress'));}
    catch(e){setError(e instanceof Error?e.message:'保存失败。');}finally{setBusy(false);}
  }
  async function cancel(action:GoalAction) {
    setBusy(true);setError('');try{const response=await fetch(`/api/v1/plants/${plantId}/actions/${action.index}/cancel`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({cancelled:!action.cancelled})});const data=await response.json();if(!response.ok)throw new Error(data.error?.message || '操作失败。');setActions(current=>current.map(item=>item.index===data.index?data:item));window.dispatchEvent(new Event('bloomate-progress'));}catch(e){setError(e instanceof Error?e.message:'操作失败。');}finally{setBusy(false);}
  }
  return <div><strong>计划步骤</strong>{feedback && <p role="status">{feedback} <a href={`#portrait-${plantId}`}>看看植物 ↑</a></p>}{loading ? <p>正在读取步骤…</p> : <><ul>{actions.map(action => <li key={action.index}>{action.text}{action.cancelled?'（已取消）':''} <button type="button" disabled={busy || action.cancelled || (paused && !action.completed)} onClick={() => void toggle(action)}>{action.completed ? '已完成，撤销' : '标记完成'}</button> <button type="button" disabled={busy || action.completed} onClick={()=>void cancel(action)}>{action.cancelled?'恢复步骤':'取消步骤'}</button>{!action.cancelled && <details className="step-tools" onToggle={event=>{if(event.currentTarget.open)setSuggestedDate(beijingToday());}}><summary>{action.due_date ? `日期：${action.due_date}` : '安排日期'}{!action.completed && ' · 修改步骤'}</summary><form onSubmit={event=>void schedule(event,action)}><label>计划日期<input type="date" name="due_date" defaultValue={action.due_date || suggestedDate} key={action.due_date || suggestedDate || 'empty'}/></label><button type="submit" disabled={busy}>保存日期</button><span className="note">未安排时建议今天，保存后生效；清空并保存可取消安排。</span></form>{!action.completed && <form onSubmit={event=>void manual(event,action.index)}><label>步骤内容<input name="text" required maxLength={500} defaultValue={action.text} key={action.text}/></label><button type="submit" disabled={busy}>保存步骤</button></form>}</details>}</li>)}</ul><details><summary>新增步骤</summary><form onSubmit={event=>void manual(event,null)}><label>新步骤<input name="text" required maxLength={500}/></label><button type="submit" disabled={busy}>添加步骤</button></form></details><AdjustmentEditor plantId={plantId} actions={actions} onChanged={refresh}/></>}{error && <p role="status">{error}</p>}</div>;
}

type GoalCollection = {title:string;plan:Plan;outcome:string;confirmed_at:string};
function GoalCollectionCard({plantId}: {plantId:string}) {
  const [saved,setSaved]=useState<GoalCollection|null>(null);const [error,setError]=useState('');
  const load=useCallback(async()=>{try{const r=await fetch(`/api/v1/plants/${plantId}/collection`);if(!r.ok)throw new Error();setSaved((await r.json()).collection);}catch{setError('暂时无法读取目标收藏。');}},[plantId]);
  useEffect(()=>{void load();window.addEventListener('bloomate-progress',load);return()=>window.removeEventListener('bloomate-progress',load);},[load]);
  return <details className="plant-block"><summary>目标收藏 <span>回看完成时的计划</span></summary>{saved ? <div><p>已完成 · {saved.confirmed_at.slice(0,10)}</p><strong>{saved.title}</strong><p>{saved.plan.summary}</p><ul>{saved.plan.steps.map((step,i)=><li key={i}>{step}</li>)}</ul></div> : <p>完成全部步骤后，计划会自动收藏。</p>}{error && <p role="status">{error}</p>}</details>;
}

type HabitPlanRevision = {id:string;status:string;before:Plan;suggestion:Plan|null;error?:{message:string}};
function HabitPlanRevisionCard({plant,onChanged}:{plant:Plant;onChanged:()=>Promise<void>}) {
  const [draft,setDraft]=useState<HabitPlanRevision|null>(null);const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const key=`bloomate-habit-revision-${plant.id}`;
  const poll=useCallback(async(id:string)=>{for(let i=0;i<75;i++){const r=await fetch(`/api/v1/habit-plan-revisions/${id}`);const d:HabitPlanRevision=await r.json();if(!r.ok)throw new Error('无法读取计划建议。');if(d.status==='error'){localStorage.removeItem(key);throw new Error(d.error?.message||'计划建议生成失败。');}if(d.status==='done'){setDraft(d);return;}if(d.status==='confirmed'||d.status==='discarded'){localStorage.removeItem(key);return;}await new Promise(resolve=>setTimeout(resolve,1000));}throw new Error('建议仍在生成，刷新后可以继续查看。');},[key]);
  useEffect(()=>{const id=localStorage.getItem(key);if(id){setBusy(true);void poll(id).catch(e=>setMessage(e instanceof Error?e.message:'无法读取计划建议。')).finally(()=>setBusy(false));}},[key,poll]);
  async function create(){setBusy(true);setMessage('');try{const r=await fetch(`/api/v1/plants/${plant.id}/habit-plan-revisions`,{method:'POST'});const d=await r.json();if(!r.ok)throw new Error(d.error?.message||'无法生成计划建议。');localStorage.setItem(key,d.id);await poll(d.id);}catch(e){setMessage(e instanceof Error?e.message:'无法生成计划建议。');}finally{setBusy(false);}}
  async function finish(confirm:boolean){if(!draft)return;setBusy(true);setMessage('');try{const r=await fetch(`/api/v1/habit-plan-revisions/${draft.id}/${confirm?'confirm':'discard'}`,{method:'POST'});const d=await r.json();if(!r.ok)throw new Error(d.error?.message||'操作失败。');localStorage.removeItem(key);setDraft(null);if(confirm){await onChanged();window.dispatchEvent(new Event('bloomate-progress'));}setMessage(confirm?'计划已按当前周期更新；已有打卡和花朵保留。':'已放弃建议，原计划不变。');}catch(e){setMessage(e instanceof Error?e.message:'操作失败。');}finally{setBusy(false);}}
  return <details className="plant-block"><summary>计划和周期不一致？<span>按当前周期重新生成</span></summary><p>如果原计划与已设置的周期不一致，可以让园丁重新建议。会发送你的习惯和已确认周期给模型，可能产生模型调用费用；确认前不会改动计划或打卡，已收藏的阶段记录也会保留。</p>{draft?.suggestion ? <div><strong>当前计划</strong><p>{draft.before.summary}</p><ul>{draft.before.steps.map((step,i)=><li key={i}>{step}</li>)}</ul><strong>按当前周期的新建议</strong><p>{draft.suggestion.summary}</p><ul>{draft.suggestion.steps.map((step,i)=><li key={i}>{step}</li>)}</ul><button type="button" disabled={busy} onClick={()=>void finish(true)}>确认更新计划</button> <button type="button" disabled={busy} onClick={()=>void finish(false)}>放弃建议</button></div> : <button type="button" disabled={busy} onClick={()=>void create()}>{busy?'园丁正在生成…':'按当前周期生成建议'}</button>}{message && <p role="status">{message}</p>}</details>;
}

function PlantCard({plant,onPlantChanged}: {plant:Plant;onPlantChanged:()=>Promise<void>}) {
  const [pause,setPause]=useState<PauseState|null>(null);const [busy,setBusy]=useState(false);const [error,setError]=useState('');const [completionStatus,setCompletionStatus]=useState<string|null>(null);const [species,setSpecies]=useState<FlowerSpecies|null>(plant.plan.flower_species ?? null);const [habitDisplay,setHabitDisplay]=useState({count:0,current:false});const setHistoryDisplay=useCallback((count:number,current:boolean)=>setHabitDisplay(old=>old.count===count && old.current===current ? old : {count,current}),[]);const [choice,setChoice]=useState<FlowerSpecies>('sunflower');const [goalActive,setGoalActive]=useState(false);
  useEffect(()=>{const refresh=()=>void fetch(`/api/v1/plants/${plant.id}/completion-notice`).then(r=>r.ok?r.json():null).then(d=>setCompletionStatus(d?.status||null)).catch(()=>setCompletionStatus(null));refresh();window.addEventListener('bloomate-progress',refresh);return()=>window.removeEventListener('bloomate-progress',refresh);},[plant.id]);
  useEffect(()=>{void fetch(`/api/v1/plants/${plant.id}/pause`).then(async r=>{if(!r.ok)throw new Error();setPause(await r.json());}).catch(()=>setError('暂时无法读取暂停状态。'));},[plant.id]);
  async function saveFlower(){setBusy(true);setError('');try{const r=await fetch(`/api/v1/plants/${plant.id}/flower`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({species:choice})});const d=await r.json();if(!r.ok)throw new Error(d.error?.message || '无法保存花种。');setSpecies(d.species);}catch(e){setError(e instanceof Error?e.message:'无法保存花种。');}finally{setBusy(false);}}
  async function togglePause() {
    if(!pause)return;setBusy(true);setError('');
    try {const response=await fetch(`/api/v1/plants/${plant.id}/pause`,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({paused:!pause.paused})});const data=await response.json();if(!response.ok)throw new Error(data.error?.message || '操作失败。');setPause(data);window.dispatchEvent(new Event('bloomate-progress'));}
    catch(e){setError(e instanceof Error?e.message:'操作失败。');}finally{setBusy(false);}
  }
  return <article className="plant-detail"><div className="plant-detail-head"><div><span className="plant-type">{plant.kind==='goal'?'目标':'习惯'} · {pause?.paused?'已暂停':completionStatus==='finished'?'已完成':completionStatus?'阶段已完成':'进行中'}</span><h2>{plant.title}</h2></div>{pause && <button type="button" className="outline-button small-button" disabled={busy} onClick={()=>void togglePause()}>{pause.paused?'恢复':'暂停'}</button>}</div>{pause?.paused && <p className="pause-note">暂停从 {pause.since} 开始。{pause.end_date ? `截止日期仍为 ${pause.end_date}，之后有 ${pause.future_days} 个计划日。` : '已有进展会保留。'}恢复不会自动延长期限；暂停及恢复当天按暂停日处理。{pause.threshold !== null && ` 阶段标准 ${pause.threshold} 次，已完成 ${pause.completed ?? 0} 次。`}{pause.future_dates.length > 0 && ` 之后计划日（最多显示10个）：${pause.future_dates.join('、')}。`}</p>}{error && <p role="status">{error}</p>}<PlantPortrait plantId={plant.id} kind={plant.kind} nodes={plant.plan.growth_nodes} species={species} completedStages={habitDisplay.count} currentCollected={habitDisplay.current}/>{plant.kind==='habit' && <HabitJourney plantId={plant.id} species={species} onHistory={setHistoryDisplay}/>} {plant.kind==='goal' && <GoalJourney plantId={plant.id} paused={pause?.paused || false} onActive={setGoalActive} onHistory={setHistoryDisplay}/>}{plant.kind==='habit' && <HabitPlanRevisionCard plant={plant} onChanged={onPlantChanged}/>}{!species && <div className="check-summary"><strong>为已有植物选择花种</strong><p>这株植物还没有记录品种，选择后会保留现有进度，确认后花种固定。</p><FlowerPicker value={choice} onChange={setChoice}/><button type="button" disabled={busy} onClick={()=>void saveFlower()}>确认花种</button></div>}<details className="plant-block"><summary>计划概览 <span>查看计划与时间</span></summary><p>{plant.plan.summary}</p>{plant.constraints?.session_budget_minutes && <p>每次最多 {plant.constraints.session_budget_minutes} 分钟{plant.constraints.habit_completion_minutes ? ` · 核心行动 ${plant.constraints.habit_completion_minutes} 分钟` : ''}</p>}{plant.plan.session_actions?.length ? <p>单次安排：{plant.plan.session_actions.map(a=>`${a.text} ${a.minutes}分钟`).join('、')}</p> : null}{plant.kind==='habit' && <ul>{plant.plan.steps.map((s,i)=><li key={i}>{s}</li>)}</ul>}</details><details className="plant-block"><summary>{plant.kind==='goal'?'行动与计划':'习惯记录与设置'} <span>{plant.kind==='goal'?'完成、安排、调整':'打卡、补签、调整周期'}</span></summary>{plant.kind==='goal' ? (goalActive ? <p>当前阶段的行动在上方。</p> : <GoalActions plantId={plant.id} paused={pause?.paused || false}/>) : <HabitActions plantId={plant.id} paused={pause?.paused || false}/>}</details><details id={`growth-${plant.id}`} className="plant-block"><summary>阶段成长 <span>设置标准、查看进度</span></summary><GrowthCard plantId={plant.id} kind={plant.kind}/></details>{plant.kind==='goal' && <GoalCollectionCard plantId={plant.id}/>}</article>;
}

type MemoryItem = {id:string;content:string};
function MemorySettings() {
  const [enabled,setEnabled]=useState(false);const [items,setItems]=useState<MemoryItem[]>([]);const [text,setText]=useState('');const [busy,setBusy]=useState(false);const [message,setMessage]=useState('');const [loaded,setLoaded]=useState(false);
  const load=useCallback(async()=>{const r=await fetch('/api/v1/memory');if(!r.ok)throw new Error('记忆暂时无法读取。');const data=await r.json();setEnabled(data.enabled);setItems(data.items);setLoaded(true);},[]);
  useEffect(()=>{void load().catch(()=>setMessage('记忆暂时无法读取。'));},[load]);
  async function preference(next:boolean){setBusy(true);setMessage('');try{const r=await fetch('/api/v1/memory/preference',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({enabled:next})});if(!r.ok)throw new Error('设置未保存。');await load();setMessage(next?'记忆已开启，只有你确认保存的内容会被使用。':'记忆已关闭，后续对话不会使用已保存的记忆。');}catch(e){setMessage(e instanceof Error?e.message:'设置未保存。');}finally{setBusy(false);}}
  async function save(event:React.FormEvent<HTMLFormElement>,id?:string){event.preventDefault();setBusy(true);setMessage('');try{const f=new FormData(event.currentTarget);const r=await fetch(id?`/api/v1/memory/items/${id}`:'/api/v1/memory/items',{method:id?'PUT':'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({content:String(f.get('content')||'')})});const d=await r.json();if(!r.ok)throw new Error(d.error?.message||'保存失败。');setText('');await load();setMessage('记忆已保存。');}catch(e){setMessage(e instanceof Error?e.message:'保存失败。');}finally{setBusy(false);}}
  async function remove(id:string){if(!window.confirm('删除这条记忆？删除后无法恢复。'))return;setBusy(true);setMessage('');try{const r=await fetch(`/api/v1/memory/items/${id}`,{method:'DELETE'});if(!r.ok)throw new Error('删除失败。');await load();setMessage('记忆已删除。');}catch(e){setMessage(e instanceof Error?e.message:'删除失败。');}finally{setBusy(false);}}
  return <details className="memory-settings"><summary>园丁记忆 · {loaded?(enabled?'已开启':'默认关闭'):'读取中'}</summary><p>只有你主动保存的偏好会被记住；开启后，它们会在之后制定目标或习惯时发送给模型服务商。请不要填写敏感信息。关闭后，后续对话不再使用记忆；已发出的请求无法撤回。</p><button type="button" disabled={busy||!loaded} onClick={()=>void preference(!enabled)}>{enabled?'关闭园丁记忆':'开启园丁记忆'}</button>{enabled && <form onSubmit={event=>void save(event)}><label>想让园丁记住什么？<input name="content" maxLength={200} required value={text} onChange={e=>setText(e.target.value)} placeholder="例如：我喜欢每次行动不超过20分钟"/></label><button type="submit" disabled={busy}>确认保存</button></form>}{items.length>0 && <div><p>已保存的记忆（关闭时保留，可随时删除）</p>{items.map(item=><form key={item.id} onSubmit={event=>void save(event,item.id)}><label>记忆内容<input name="content" maxLength={200} required defaultValue={item.content} key={item.content} disabled={!enabled}/></label><button type="submit" disabled={busy||!enabled}>保存修改</button> <button type="button" disabled={busy} onClick={()=>void remove(item.id)}>删除</button></form>)}</div>}{message && <p role="status">{message}</p>}</details>;
}

export default function Home() {
  const [activeView,setActiveView] = useState<'today'|'plan'|'garden'>('today');
  const [selectedPlant,setSelectedPlant] = useState<string|null>(null);const [gardenTab,setGardenTab]=useState<'plants'|'collections'>('plants');
  const [kind, setKind] = useState<'goal'|'habit'>('goal');
  const [goal, setGoal] = useState('');
  const [background, setBackground] = useState('');
  const [goalDays, setGoalDays] = useState('');
  const [budget, setBudget] = useState('');
  const [completion, setCompletion] = useState('');
  const [habitStart,setHabitStart]=useState(beijingToday);const [habitEnd,setHabitEnd]=useState('');const [habitDays,setHabitDays]=useState<number[]>([0,1,2,3,4,5,6]);const [habitStandard,setHabitStandard]=useState('');const [habitThreshold,setHabitThreshold]=useState<number|null>(null);
  const startMs=Date.parse(`${habitStart}T00:00:00Z`),endMs=Date.parse(`${habitEnd}T00:00:00Z`);
  const oneDayHabit=!!habitStart && habitStart===habitEnd && Number.isFinite(startMs);
  const effectiveHabitDays=oneDayHabit?[(new Date(startMs).getUTCDay()+6)%7]:habitDays;let habitPlanned=0;
  if(Number.isFinite(startMs)&&Number.isFinite(endMs)&&endMs>=startMs&&endMs-startMs<=3660*86400000){for(let t=startMs;t<=endMs;t+=86400000)if(effectiveHabitDays.includes((new Date(t).getUTCDay()+6)%7))habitPlanned++;}

  const [constraints, setConstraints] = useState<Constraints>({session_budget_minutes:null,habit_completion_minutes:null});
  const [plan, setPlan] = useState<Plan|null>(null);
  const [job, setJob] = useState('');
  const [question, setQuestion] = useState('');
  const [answer, setAnswer] = useState('');
  const [plants, setPlants] = useState<Plant[]>([]);
  const [gardenStatus,setGardenStatus]=useState<'loading'|'ready'|'error'>('loading');
  const [message, setMessage] = useState('');
  const [busy, setBusy] = useState(false);
  const loadGarden = useCallback(async () => {
    try { const res = await fetch('/api/v1/garden'); if (!res.ok) throw new Error(); const data = await res.json(); setPlants(data.plants); setGardenStatus('ready'); }
    catch { setGardenStatus('error'); setMessage('花园暂时无法连接，请检查本地服务。'); }
  }, []);
  const poll = useCallback(async function pollJob(jobId: string): Promise<void> {
    setJob(jobId); localStorage.setItem('bloomate-active-job', jobId);
    for (let i = 0; i < 75; i++) {
      await new Promise(resolve => setTimeout(resolve, 1000));
      const response = await fetch(`/api/v1/plans/${jobId}`); const result = await response.json();
      if (!response.ok || result.status === 'error') throw new Error(result.error?.message || '计划生成失败。');
      if (result.status === 'superseded' && result.next_job_id) return pollJob(result.next_job_id);
      if (result.status === 'done') { setPlan(result.proposal); setQuestion(result.question || ''); setConstraints(result.constraints); if(result.kind==='habit'||result.kind==='goal')setKind(result.kind); return; }
    }
    throw new Error('等待时间较长，请稍后再试。');
  }, []);
  useEffect(() => {
    void loadGarden();
    const saved = localStorage.getItem('bloomate-active-job');
    if (saved) {
      setActiveView('plan');
      setJob(saved);
      fetch(`/api/v1/plans/${saved}`).then(r => r.json()).then(result => {
        if (result.status === 'done') { setPlan(result.proposal); setQuestion(result.question || ''); setConstraints(result.constraints); if(result.kind==='habit'||result.kind==='goal')setKind(result.kind); }
        else if (result.status === 'error') setMessage(result.error?.message || '上一次生成中断，请重新开始。');
        else if (result.status === 'superseded' && result.next_job_id) void poll(result.next_job_id).catch(() => setMessage('上一次对话暂时无法读取。'));
        else if (result.status === 'pending' || result.status === 'running') void poll(saved).catch(() => setMessage('上一次对话尚未完成，请稍后重试。'));
      }).catch(() => setMessage('上一次对话暂时无法读取。'));
    }
  }, [loadGarden, poll]);
  async function propose(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (kind==='habit' && (!habitPlanned || !habitStandard.trim() || (habitThreshold!==null && (habitThreshold<1 || habitThreshold>habitPlanned)))) {setMessage('请检查日期、计划日和阶段完成次数。');return;}
    if (kind === 'habit' && budget && completion && Number(completion) > Number(budget)) { setMessage('核心行动的完成分钟数超过可用时间，请调整后继续。'); return; }
    setBusy(true); setMessage(''); setPlan(null);
    try {
      const response = await fetch('/api/v1/plans', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({kind, goal, background, availability:kind==='habit'?(budget?`每次最多 ${Number(budget)} 分钟`:'每次可投入时间不确定，请提出可调整的建议，不要当作用户已确认的时间。'):`${goalDays?`希望 ${Number(goalDays)} 天内完成`: '未单独指定期限，请结合目标描述；仍不确定时提出可调整的期限建议'}；${budget?`每次最多 ${Number(budget)} 分钟`:'每次可投入时间不确定，请提出可调整的建议，不要当作用户已确认的时间'}`, session_budget_minutes:budget ? Number(budget) : null, habit_completion_minutes:kind==='habit' && completion ? Number(completion) : null,habit_schedule:kind==='habit'?{start_date:habitStart,end_date:habitEnd,timezone:'Asia/Shanghai',weekdays:effectiveHabitDays,completion_standard:habitStandard,growth_threshold:oneDayHabit?1:(habitThreshold ?? habitPlanned)}:null}) });
      const body = await response.json(); if (!response.ok) throw new Error(body.error?.message || '无法创建计划。');
      setQuestion(''); await poll(body.id);
    } catch (error) { setMessage(error instanceof Error ? error.message : '暂时无法生成计划。'); }
    finally { setBusy(false); }
  }
  async function reply(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault(); setBusy(true); setMessage('');
    try {
      const res = await fetch(`/api/v1/plans/${job}/reply`, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify({answer})});
      const data = await res.json(); if (!res.ok) throw new Error(data.error?.message || '暂时无法继续对话。');
      setAnswer(''); setQuestion(''); await poll(data.id);
    } catch (error) { setMessage(error instanceof Error ? error.message : '暂时无法继续对话。'); }
    finally { setBusy(false); }
  }
  async function confirm() {
    if (kind==='goal' && plan?.growth_nodes && (plan.growth_nodes.some((n,i,a)=>!Number.isInteger(n) || n<1 || n>99 || (i>0 && n<=a[i-1])) || plan.growth_nodes.length!==4)) {setMessage('成长节点须为 1 到 99 的递增整数。');return;}
    if (plan?.session_actions?.some(a => a.minutes === null || a.minutes < 1)) { setMessage('请为每项行动填写大于零的分钟数。'); return; }
    setBusy(true); setMessage('');
    try {
      const res = await fetch(`/api/v1/proposals/${job}/confirm`, {method:'POST', headers:{'Content-Type':'application/json'}, body:JSON.stringify(plan ? {...plan,flower_species:plan.flower_species ?? 'sunflower',...(kind==='goal'?{growth_nodes:plan.growth_nodes ?? [14,42,71,85]}:{})} : plan)}); const data = await res.json();
      if (!res.ok) throw new Error(data.error?.message || '种植失败。');
      setPlan(null); localStorage.removeItem('bloomate-active-job'); setMessage('种子已种下。每一步都值得被看见。'); await loadGarden(); setSelectedPlant(data.id); setActiveView('garden'); window.dispatchEvent(new Event('bloomate-progress'));
    } catch (error) { setMessage(error instanceof Error ? error.message : '种植失败，请重试。'); }
    finally { setBusy(false); }
  }
  function changeKind(nextKind: 'goal'|'habit') {
    if (nextKind === kind || busy) return;
    setKind(nextKind);
    setGoal(''); setBackground(''); setGoalDays(''); setBudget(''); setCompletion('');setHabitStart(beijingToday());setHabitEnd('');setHabitDays([0,1,2,3,4,5,6]);setHabitStandard('');setHabitThreshold(null);
    setQuestion(''); setAnswer(''); setPlan(null); setJob(''); setMessage('');
    setConstraints({session_budget_minutes:null, habit_completion_minutes:null});
    localStorage.removeItem('bloomate-active-job');
  }
  return <main><header><div className="brand"><span>✿</span> Bloomate</div><div className="header-actions"><div className="notice">本机体验中 · 尚未保存到账户</div><CareBox onOpenPlant={id=>{setSelectedPlant(id);setGardenTab('plants');setActiveView('garden');}}/></div></header><nav className="main-nav" aria-label="主要功能">{([{id:'today',label:'今日行动',hint:'看看今天做什么'},{id:'plan',label:'制定计划',hint:'和园丁聊聊'},{id:'garden',label:'我的花园',hint:'管理目标与习惯'}] as const).map(item=><button key={item.id} type="button" aria-current={activeView===item.id?'page':undefined} className={activeView===item.id?'nav-item active':'nav-item'} onClick={()=>setActiveView(item.id)}><span>{item.label}</span><small>{item.hint}</small></button>)}</nav>
    <div hidden={activeView!=='today'}><TodayActions plants={plants} gardenStatus={gardenStatus} onReloadGarden={()=>void loadGarden()} onOpenPlant={id=>{setSelectedPlant(id);setGardenTab('plants');setActiveView('garden');}} onCreate={()=>setActiveView('plan')}/></div><div hidden={activeView!=='plan'} className="plan-view"><div className="view-heading"><div><div className="eyebrow">A NEW BEGINNING</div><h1>一起种下一个想法。</h1><p>告诉园丁你的目标或习惯，我们一起找到开始的方式。</p></div></div><div className="plan-layout"><aside className="plan-aside"><div className="aside-symbol">✿</div><h2>从一小步开始</h2><p>不用想得很完整。说说你想做什么、能投入多少时间，就可以开始。</p><div className="aside-steps"><span>01 · 说出想法</span><span>02 · 看看建议</span><span>03 · 确认并种下</span></div></aside><section className="card plan-card"><div className="card-top"><span className="icon">✧</span><div><h2>和园丁聊聊</h2><p>从一个想法开始就好</p></div></div>
      <p className="privacy">本机测试使用 DeepSeek：你填写的内容会发送至该服务处理，请勿输入敏感信息。</p><MemorySettings/><form onSubmit={propose}><div className="choice"><button type="button" disabled={busy} className={kind==='goal'?'active':''} onClick={()=>changeKind('goal')}>完成一个目标</button><button type="button" disabled={busy} className={kind==='habit'?'active':''} onClick={()=>changeKind('habit')}>培养一个习惯</button></div>
      <label>你想做什么？<textarea required minLength={2} maxLength={500} value={goal} onChange={e=>setGoal(e.target.value)} placeholder={kind==='goal'?'例如：一个月内准备好产品经理面试':'例如：养成每天阅读的习惯'}/></label>
      <label>现在的情况 <small>选填</small><input maxLength={1000} value={background} onChange={e=>setBackground(e.target.value)} placeholder="已有的基础、遇到的困难…"/></label>
      {kind==='goal' && <label>希望几天内完成？ <small>选填，不确定可以留空</small><input type="number" min={1} max={3650} step={1} value={goalDays} onChange={e=>setGoalDays(e.target.value)} placeholder="例如：7"/></label>}
      <label>每次最多可以投入多少分钟？ <small>选填，不确定可以留空</small><input type="number" min={1} max={720} step={1} value={budget} onChange={e=>setBudget(e.target.value)} placeholder="例如：20"/></label>
      {kind==='habit' && <label>每次核心行动要做满多少分钟？ <small>选填</small><input type="number" min={1} max={720} step={1} value={completion} onChange={e=>setCompletion(e.target.value)} placeholder="例如：读满10分钟"/></label>}
      {kind==='habit' && <fieldset className="habit-plan-schedule" disabled={busy || !!plan || !!question}><legend>先确定这个习惯的阶段周期</legend><p>园丁会按你选的日期和计划日制定计划；开始和结束同一天就是一天。</p><label>开始日期<input type="date" value={habitStart} required onChange={e=>{setHabitStart(e.target.value);setHabitThreshold(null);}}/></label><label>结束日期<input type="date" min={habitStart} value={habitEnd} required onChange={e=>{setHabitEnd(e.target.value);setHabitThreshold(null);}}/></label>{oneDayHabit ? <p className="single-day-hint">已安排这一天，完成 1 次即可达到阶段目标。</p> : <div className="weekday-choices"><span>每周哪几天做？</span>{weekdayNames.map((name,i)=><label key={name}><input type="checkbox" checked={habitDays.includes(i)} onChange={e=>{setHabitThreshold(null);setHabitDays(old=>e.target.checked?[...old,i]:old.filter(n=>n!==i));}}/>{name}</label>)}</div>}<label>每次怎样算完成？<input value={habitStandard} required maxLength={200} onChange={e=>setHabitStandard(e.target.value)} placeholder="例如：连续阅读十分钟"/></label>{!oneDayHabit && <><label>这个阶段完成多少次算达标？<input type="number" min={1} max={habitPlanned || 1} required value={habitThreshold ?? (habitPlanned || '')} onChange={e=>setHabitThreshold(e.target.value ? Number(e.target.value):null)}/></label><p className="note">{habitPlanned ? `所选周期有 ${habitPlanned} 个计划日；默认建议完成全部，可自行修改。` : '选择日期与计划日后显示可完成次数。'}</p></>}</fieldset>}
      {kind==='habit' && (plan || question) && <button type="button" onClick={()=>{setPlan(null);setQuestion('');setJob('');localStorage.removeItem('bloomate-active-job');}}>重新设置周期并制定</button>}
      <button className="primary" disabled={busy}>{busy?'园丁正在想一想…':'一起制定计划  →'}</button></form>
      {message && <div className="message" role="status">{message}</div>}
      {question && <form className="proposal" onSubmit={reply}><div className="eyebrow">园丁想再了解一点</div><p>{question}</p><label>你的回答<textarea value={answer} onChange={e=>setAnswer(e.target.value)} required maxLength={1000}/></label><button className="primary" disabled={busy}>继续对话</button></form>}
      {plan && <div className="proposal"><div className="eyebrow">一份给你的建议</div><label>计划名称<input value={plan.title} maxLength={100} onChange={e=>setPlan({...plan, title:e.target.value})}/></label><label>计划说明<textarea value={plan.summary} maxLength={500} onChange={e=>setPlan({...plan, summary:e.target.value})}/></label><label>全程行动步骤（每行一条）<textarea value={plan.steps.join("\n")} onChange={e=>setPlan({...plan, steps:e.target.value.split("\n")})}/></label><div className="check-summary"><strong>这次种什么花？</strong><p>{plan.flower_reason && plan.flower_species ? `园丁推荐${flowerNames[plan.flower_species]}：${plan.flower_reason}` : plan.flower_species ? '已选择花种，可以再换。' : '园丁暂未给出推荐，先为你建议向日葵，可以更换。'}</p><FlowerPicker value={plan.flower_species ?? 'sunflower'} onChange={f=>setPlan({...plan,flower_species:f,flower_reason:null})}/></div>{kind==='goal' && <div className="check-summary"><strong>植物的成长节点</strong><p>按计划进度逐渐生长，你可以修改建议的百分比。完成全部步骤后开花；目标是否真正完成由你确认。</p>{!plan.growth_nodes && <p className="note">园丁没有给出节点，已使用默认建议。</p>}{['小芽','发芽','枝叶','花苞'].map((label,i)=><label key={label}>{label}（计划进度 %）<input type="number" min={1} max={99} value={(plan.growth_nodes ?? [14,42,71,85])[i]} onChange={e=>setPlan({...plan,growth_nodes:(plan.growth_nodes ?? [14,42,71,85]).map((n,j)=>j===i?Number(e.target.value):n)})}/></label>)}</div>}{constraints.habit_schedule && <div className="check-summary"><strong>本次习惯周期</strong><p>{constraints.habit_schedule.start_date} 至 {constraints.habit_schedule.end_date} · {constraints.habit_schedule.weekdays.map(d=>weekdayNames[d]).join('、')}</p><p>每次：{constraints.habit_schedule.completion_standard}；阶段完成 {constraints.habit_schedule.growth_threshold} 次。确认计划时一起保存。</p></div>}<div className="check-summary"><strong>确认前检查</strong><p>每次可用时间：{constraints.session_budget_minutes === null ? '未填写，需自行核对' : `${constraints.session_budget_minutes} 分钟`}</p>{constraints.habit_completion_minutes !== null && <p>你填写的核心行动完成标准：{constraints.habit_completion_minutes} 分钟</p>}{plan.session_actions?.length ? <div><p>第1次行动示例，合计：{plan.session_actions.reduce((sum,a)=>sum+(a.minutes ?? 0),0)} 分钟</p>{plan.session_actions.map((action,i)=><div className="action-row" key={i}><input aria-label={`第${i+1}项动作`} value={action.text} onChange={e=>setPlan({...plan,session_actions:plan.session_actions!.map((a,n)=>n===i?{...a,text:e.target.value}:a)})}/><input aria-label={`第${i+1}项分钟`} type="number" min={1} max={720} value={action.minutes ?? ''} onChange={e=>setPlan({...plan,session_actions:plan.session_actions!.map((a,n)=>n===i?{...a,minutes:e.target.value === '' ? null : Number(e.target.value)}:a)})}/><span>{action.kind==='core'?'核心行动':'准备/其他'}</span></div>)}</div> : <p>没有可自动核对的单次时间安排，请自行核对。</p>}<p className="note">程序只核对上面的单次安排及部分常见表述，无法检查全部计划的时间或事实；请逐条确认。</p></div><button className="primary" onClick={confirm} disabled={busy}>确认计划，种下种子</button><p className="note">确认前，这只是一份建议。</p></div>}
    </section></div></div><div hidden={activeView!=='garden'} className="garden-view"><div className="view-heading"><div><div className="eyebrow">YOUR LITTLE GARDEN</div><h1>我的小花园。</h1><p>每一株植物，都记录着你正在做的事。</p></div><button type="button" className="outline-button" onClick={()=>setActiveView('plan')}>＋ 制定新计划</button></div><div className="garden-tabs" role="group" aria-label="花园内容"><button type="button" aria-pressed={gardenTab==='plants'} onClick={()=>setGardenTab('plants')}>我的植物</button><button type="button" aria-pressed={gardenTab==='collections'} onClick={()=>setGardenTab('collections')}>我的收藏</button></div>{gardenTab==='collections'?<CollectionGallery onOpenPlant={id=>{setSelectedPlant(id);setGardenTab('plants');}}/>:plants.length===0?<div className="card empty"><div className="sprout">🌱</div><h3>这里还空着一小块土地</h3><p>和园丁聊聊，种下属于你的第一株植物吧。</p><button type="button" className="text-button" onClick={()=>setActiveView('plan')}>去制定计划 →</button></div>:<div className="garden-layout"><aside className="card plant-picker"><div className="section-heading"><h2>我的植物</h2><span className="count-badge">{plants.length}</span></div><p className="muted">选择一株，查看行动与成长。</p><div className="plant-picker-list">{plants.map(plant=><button type="button" key={plant.id} className={selectedPlant===plant.id?'plant-pick active':'plant-pick'} aria-pressed={selectedPlant===plant.id} onClick={()=>setSelectedPlant(plant.id)}><span className="plant-pick-icon" aria-hidden="true">🌱</span><span><strong>{plant.title}</strong><small>{plant.kind==='goal'?'目标':'习惯'}</small></span><span className="plant-arrow" aria-hidden="true">›</span></button>)}</div></aside><section className="card garden-content" aria-label="植物详情">{selectedPlant===null && <div className="garden-placeholder"><span aria-hidden="true">✿</span><h2>选一株植物看看</h2><p>这里可以管理行动、习惯打卡和阶段成长。</p></div>}{plants.map(plant=><div key={plant.id} hidden={selectedPlant!==plant.id}><PlantCard plant={plant} onPlantChanged={loadGarden}/></div>)}</section></div>}</div><footer>慢一点也没关系，你正在生长。 ✿</footer></main>;
}
